/* Pop-out explainers for the real events and institutions the game mentions.
   Owner request (11 Nov 2026): "a little pop out explainer" on every event, for players who will not
   know, say, what Mafeking night was. The first mention of each event in a quiz question, scene or
   outcome becomes a dotted link; tapping it opens a short card.
   Rules: explain only what was known at the time of the scene (no spoilers of later outcomes beyond
   the event itself); British politicians keep their echo names; invented alternate-history events
   get no card, because they did not happen.
   `m` is a regular expression (source string) matched against the plain text; the first match wins. */
(function () {
  const TM = (window.TM = window.TM || {});

  TM.GLOSS = [
    // ── Victorian childhood ──
    { id: 'mafeking', m: 'Mafeking', title: 'Mafeking night', date: '18 May 1900',
      text: 'Mafeking, a small railway town in South Africa, was besieged by the Boers for 217 days, held by a garrison under Colonel Robert Baden-Powell. When news of its relief reached London on the evening of 18 May 1900, crowds poured into the streets in such wild celebration that "to maffick" entered the language.' },
    { id: 'franchise', m: 'the Bill that would give the vote|Franchise Bill|first in which farm labourers will vote', title: 'The Third Reform Act', date: '1884–85',
      text: 'Until 1884 most men in the country districts had no vote. A Liberal Bill extended the vote to farm labourers and miners on the same terms as town householders, adding about two million voters. The Lords blocked it in July 1884, huge demonstrations followed, and a compromise passed it that winter. Women still had no vote at all.' },
    { id: 'khartoum', m: 'Khartoum|General Gordon', title: 'Gordon and Khartoum', date: 'January 1885',
      text: 'General Charles Gordon was sent to the Sudan to evacuate Egyptian garrisons from the Mahdi\'s rising, and instead held on in Khartoum. A relief expedition was sent late. The city fell on 26 January 1885 and Gordon was killed; the relief steamers arrived two days after. The public blamed the government bitterly.' },
    { id: 'gom', m: 'Grand Old Man', title: 'The Grand Old Man', date: '1880s',
      text: 'The nickname of the Liberal leader Mr Gladwyn, four times Prime Minister and the dominant figure of Victorian politics. After Khartoum, crowds turned his initials round: G.O.M. became M.O.G., the Murderer of Gordon.' },
    { id: 'primrose', m: 'Primrose League', title: 'The Primrose League', date: 'founded 1883',
      text: 'A Conservative organisation founded in 1883 in memory of a late Tory Prime Minister said to have loved primroses. With knights, dames, badges, fêtes and magic-lantern shows, it brought hundreds of thousands of ordinary people, women included, into Tory politics before women could vote.' },
    { id: 'riots-1886', m: 'crowd of unemployed men', title: 'The West End riots', date: '8 February 1886',
      text: 'A bad winter left thousands out of work. After a meeting of the unemployed in Trafalgar Square, a crowd jeered at from the windows of the Pall Mall clubs answered with stones, then smashed and looted its way through St James\'s and Piccadilly. The head of the Metropolitan Police resigned.' },
    { id: 'chancellor', m: 'Chancellor of the Exchequer', title: 'Chancellor of the Exchequer', date: '',
      text: 'The minister in charge of the Treasury: taxes, spending and the Budget. The second most powerful post in most governments, and often the last step before Prime Minister.' },
    { id: 'home-rule', m: 'Home Rule', title: 'Irish Home Rule', date: '1886–1914',
      text: 'The demand that Ireland have its own Parliament in Dublin for Irish affairs while staying under the Crown. Liberal Home Rule Bills were defeated in 1886 and 1893; a third passed in 1914 but was suspended for the war. Protestant Ulster resisted it fiercely, and it split the Liberal Party.' },
    { id: 'strangers', m: 'Strangers\' Gallery', title: 'The Strangers\' Gallery', date: '',
      text: 'The public gallery of the House of Commons, where visitors with a ticket from a Member can watch debates from above the Speaker\'s chair. "Strangers" is the House\'s word for anyone who is not a Member.' },
    { id: 'sandhurst', m: 'Sandhurst', title: 'Sandhurst', date: '',
      text: 'The Royal Military College at Sandhurst trained officers for the infantry and cavalry. Entry was by competitive examination, and a boy who did badly might be offered only the cavalry, which was grander but far more expensive, since officers paid for their own horses and mess bills.' },
    { id: 'empire-promenade', m: 'Empire\'s famous promenade', title: 'The Empire Theatre row', date: 'November 1894',
      text: 'The promenade bar of the Empire music hall in Leicester Square was notorious as a place where men met prostitutes. Purity campaigners got the London County Council to screen it off with canvas. On 3 November 1894 a crowd of young men, cadets among them, tore the screens down.' },
    { id: 'cuba', m: 'Cuba', title: 'The Cuban War of Independence', date: '1895–98',
      text: 'Cuban rebels rose against Spanish rule in 1895, fighting a guerrilla war in the cane fields and scrub. Spain sent huge armies and herded country people into camps. In 1898 the United States intervened, and Spain lost Cuba.' },
    { id: 'kruger', m: 'Kaiser\'s telegram', title: 'The Jameson Raid and the Kruger telegram', date: 'January 1896',
      text: 'At New Year 1896 a private force of about six hundred men rode into the Boer republic of the Transvaal, hoping to set off a rising of British settlers. They were rounded up in days. Kaiser Wilhelm II telegraphed President Kruger to congratulate him, and Britain was furious with Germany.' },
    { id: 'frontier', m: 'North-West Frontier|Frontier', title: 'The North-West Frontier', date: '',
      text: 'The mountainous border between British India and Afghanistan, home to Pathan tribes who were never fully ruled by anyone. The British held it with forts, bribes, punitive columns and political officers. In 1897 a great rising swept the frontier and took two years and tens of thousands of troops to put down.' },
    { id: 'mamund', m: 'Mamund valley', title: 'The Malakand campaign', date: '1897',
      text: 'In 1897 tribes rose against the British garrison at the Malakand Pass. A field force under General Sir Bindon Blood was sent to punish them. On 16 September 1897 a brigade was caught among the villages of the Mamund valley and lost heavily; the army then burned the valley\'s villages in reprisal.' },
    { id: 'omdurman', m: '21st Lancers|Omdurman', title: 'Omdurman', date: '2 September 1898',
      text: 'General Kitchener\'s army reconquered the Sudan and met the Mahdist army outside Omdurman. Machine guns and rifles killed about ten thousand of them in a morning for fewer than fifty British dead. The 21st Lancers made one of the last full cavalry charges of the British Army, into a hidden ravine full of men.' },
    { id: 'fashoda', m: 'Fashoda', title: 'The Fashoda crisis', date: 'September–November 1898',
      text: 'A small French expedition planted its flag at Fashoda on the upper Nile, in country Britain claimed for Egypt. Kitchener arrived with gunboats. For weeks the two countries stood close to war, until France backed down. The fright helped push them into friendship a few years later.' },
    { id: 'boer-war', m: 'War with the Boers|at war with the Boers|against the Boers|Boer lines|Pretoria has fallen', title: 'The Boer War', date: '1899–1902',
      text: 'War between the British Empire and the two Boer republics, the Transvaal and the Orange Free State, over gold, the rights of British settlers and who would rule South Africa. The Boers, farmers on horseback with modern rifles, humiliated the British army at first. Britain needed 450,000 troops to win.' },
    { id: 'black-week', m: 'Black Week|Colenso|Tugela', title: 'Black Week', date: '10–15 December 1899',
      text: 'In one week the British army lost three battles to the Boers: Stormberg, Magersfontein and Colenso, on the Tugela river, where guns were pushed so far forward that their crews were shot down and ten of them were lost. The shock brought volunteers flooding in from all over the Empire.' },
    { id: 'spion-kop', m: 'Spion Kop', title: 'Spion Kop', date: '23–24 January 1900',
      text: 'A hill on the road to besieged Ladysmith, seized by British infantry at night. At dawn they found the trenches too shallow and overlooked from three sides. They were shot to pieces all day and withdrew in the dark. More than 1,500 British troops were killed, wounded or captured.' },
    { id: 'ladysmith', m: 'Ladysmith', title: 'The siege of Ladysmith', date: 'November 1899 – February 1900',
      text: 'A garrison of about 13,000 troops was trapped by the Boers in the Natal town of Ladysmith for 118 days, eating horses. The relief army fought its way up the Tugela, defeated again and again, until it broke through at the end of February 1900.' },
    { id: 'paardeberg', m: 'Paardeberg', title: 'Paardeberg', date: 'February 1900',
      text: 'General Cronjé\'s Boer army was surrounded in the bed of the Modder river at Paardeberg. After ten days of shelling he surrendered with about 4,000 men on 27 February 1900, the first great British victory of the war.' },
    { id: 'boxers', m: 'Boxers|legations', title: 'The Boxer Rising', date: '1899–1901',
      text: 'A movement in northern China against foreigners and Christians, which the Chinese court came to back. In June 1900 the foreign legations in Peking were besieged for fifty-five days. Eight foreign powers sent troops, stormed the Taku forts at the river mouth, and relieved the legations in August.' },
    { id: 'khaki', m: 'khaki election|called an election on the war', title: 'The khaki election', date: 'October 1900',
      text: 'An election called in wartime to cash in on patriotism, named after the new khaki uniforms. In 1900 the Conservatives went to the country while the Boer War seemed won, and painted opponents of the war as traitors. They won comfortably. The name stuck to any wartime election.' },
    { id: 'old-queen', m: 'old Queen is dead', title: 'The death of Queen Victoria', date: '22 January 1901',
      text: 'Queen Victoria died at Osborne after nearly sixty-four years on the throne. Most of her subjects had never known another monarch. Her son became Edward VII.' },
    { id: 'camps', m: 'herding of women and children into camps', title: 'The Boer War camps', date: '1900–02',
      text: 'To starve the Boer guerrillas, the army burned farms and moved Boer women and children, and black Africans, into concentration camps. Disease killed about 26,000 Boers, most of them children, and at least 14,000 Africans. The camps caused a scandal in Britain.' },
    { id: 'tariffs', m: 'Free Trade|campaign for tariffs|for tariffs', title: 'Free Trade and Tariff Reform', date: '1903–06',
      text: 'Britain had bought food and goods from anywhere, without duties, since the 1840s. In 1903 the Colonial Secretary, Mr Chambers, launched a campaign for tariffs on foreign imports, with preference for the Empire. His opponents said it meant dear food for the poor. The row split the Conservatives.' },
    { id: 'chinese-labour', m: 'Chinese labour', title: '"Chinese slavery"', date: '1904–06',
      text: 'After the Boer War, mine owners brought some 60,000 Chinese labourers to the Rand gold mines on harsh contracts and kept them in compounds. Liberals and trade unionists called it slavery, and it helped sink the Conservative government in 1906.' },
    { id: 'peoples-budget', m: 'thrown out the Budget|Peers against the People', title: 'The People\'s Budget', date: '1909–10',
      text: 'In 1909 the Liberal Chancellor, Mr Lloyd Gwynne, raised taxes on the rich and on land to pay for old-age pensions and battleships. The House of Lords, by custom, never rejected a Budget. It rejected this one, and two general elections were fought in 1910 on whether the peers or the people should rule.' },
    { id: 'parliament-act', m: 'swamp them|last ditch', title: 'The Parliament Act', date: '1911',
      text: 'To pass a law cutting the Lords\' power to delay Bills, the Liberals got the King to promise to create hundreds of new Liberal peers if needed. Tory "ditchers" wanted to fight anyway; "hedgers" wanted to give in. The Lords gave way in August 1911 by 131 votes to 114.' },
    { id: 'tonypandy', m: 'Tonypandy|Rhondda', title: 'Tonypandy', date: 'November 1910',
      text: 'During a bitter coal dispute in the Rhondda valley, striking miners rioted at Tonypandy and shop windows were smashed. The Home Secretary held back troops and sent Metropolitan Police first, then let soldiers follow. In the valleys he was remembered for sending troops at all.' },
    { id: 'sidney-street', m: 'Sidney Street', title: 'The siege of Sidney Street', date: '3 January 1911',
      text: 'Latvian anarchists who had shot dead three policemen during a burglary in Houndsditch were cornered in a house in Stepney. Scots Guards were called in, and the Home Secretary came to watch. The house caught fire, and the firemen were held back until it had burned out.' },
    { id: 'agadir', m: 'Agadir', title: 'The Agadir crisis', date: 'July 1911',
      text: 'Germany sent a gunboat to the Moroccan port of Agadir to press France for concessions. Britain stood by France, and for a summer war seemed near. The scare exposed how unready the Admiralty was and brought in a new First Lord to build a naval war staff.' },
    { id: 'suffragettes', m: 'suffragettes|campaigning for the vote', title: 'The suffragettes', date: '1903–14',
      text: 'Women campaigning for the vote. The militant Women\'s Social and Political Union smashed windows, burned empty buildings and heckled ministers. Hundreds were imprisoned; hunger strikers were force-fed. Women over thirty won the vote in 1918, and on equal terms with men in 1928.' },
    { id: 'volunteers', m: 'hundred thousand Volunteers|drill with the Volunteers', title: 'The Ulster and Irish Volunteers', date: '1913–14',
      text: 'In 1913 Ulster Protestants formed the Ulster Volunteers, about 100,000 strong, to resist Home Rule by force, and smuggled in German rifles. Irish nationalists answered with the Irish Volunteers. By the summer of 1914 Ireland had two private armies and seemed close to civil war.' },
    { id: 'curragh', m: 'Curragh', title: 'The Curragh incident', date: 'March 1914',
      text: 'Cavalry officers at the Curragh camp near Dublin, given the choice, said they would resign rather than be ordered north against Ulster. The government backed down and ministers resigned. It showed that the Army could not be relied on to enforce Home Rule.' },
    { id: 'july-1914', m: 'ultimatum to Serbia', title: 'The July Crisis', date: 'July 1914',
      text: 'After the murder of Archduke Franz Ferdinand in Sarajevo, Austria-Hungary sent Serbia an ultimatum meant to be refused. Russia backed Serbia, Germany backed Austria, France was allied to Russia. In a week Europe went to war. Britain declared war on Germany on 4 August after the invasion of Belgium.' },
    { id: 'recruiting', m: 'recruiting offices?|recruiting posters', title: 'The rush to enlist', date: 'August–September 1914',
      text: 'Britain had no conscription in 1914. Lord Kitchener called for volunteers, and over 750,000 men joined up in the first two months, many in "Pals battalions" of friends and workmates. Conscription came in 1916.' },
    { id: 'dardanelles', m: 'Dardanelles|Gallipoli', title: 'The Dardanelles and Gallipoli', date: '1915',
      text: 'A plan to force the straits to Constantinople with warships and knock Turkey out of the war. On 18 March 1915 three battleships were sunk by mines and the fleet turned back. Troops landed at Gallipoli in April and were pinned on the beaches until they were evacuated in January 1916.' },
    { id: 'ploegsteert', m: 'Ploegsteert', title: 'Plugstreet', date: '1914–18',
      text: 'Ploegsteert, a Belgian village south of Ypres, called Plugstreet by the troops. A comparatively quiet sector of the Western Front, where battalions were sent to learn trench life. Quiet still meant shelling, snipers and night patrols into No Man\'s Land.' },
    { id: 'western-front', m: 'Western Front', title: 'The Western Front', date: '1914–18',
      text: 'The line of trenches from the Channel coast to Switzerland, where the war in France and Belgium settled after the autumn of 1914. For more than three years neither side could break through, and attacks cost tens of thousands of lives for a few miles.' },
    { id: 'russia-1917', m: 'Tsar has abdicated|Lenin', title: 'The Russian Revolution', date: '1917',
      text: 'In March 1917 bread riots and a mutiny of the Petrograd garrison brought down the Tsar. A Provisional Government tried to fight on. The Germans sent the Bolshevik leader Lenin home from Switzerland in a sealed train, and in November his party seized power and took Russia out of the war.' },
    { id: 'arras', m: 'Arras', title: 'The Battle of Arras', date: 'April–May 1917',
      text: 'A British offensive in northern France, opened on 9 April 1917 after a huge bombardment. The Canadians took Vimy Ridge. Then the attack bogged down, and its daily losses were the heaviest of any British battle of the war.' },
    { id: 'zeebrugge', m: 'Zeebrugge', title: 'The Zeebrugge raid', date: '23 April 1918',
      text: 'A naval raid to block the Belgian port used by German U-boats. Old cruisers were sunk in the canal mouth while marines and sailors stormed the harbour Mole under fire. It was hailed as a triumph, though the canal was only partly blocked. Eight Victoria Crosses were won.' },
    { id: 'holzminden', m: 'Holzminden', title: 'The Holzminden tunnel', date: 'July 1918',
      text: 'Holzminden was a harsh German camp for British officers. Prisoners dug a tunnel for nine months, and on the night of 23–24 July 1918 twenty-nine escaped through it. Ten reached neutral Holland, the largest successful escape of the war.' },
    { id: 'influenza', m: 'influenza', title: 'The Spanish flu', date: '1918–19',
      text: 'A pandemic that killed perhaps 50 million people worldwide and about 228,000 in Britain. Unusually, it killed the young and fit. Victims could turn blue from lack of oxygen and die within days. The worst wave struck in the autumn of 1918, just as the war ended.' },
    { id: 'armistice', m: 'Armistice', title: 'The Armistice', date: '11 November 1918',
      text: 'The ceasefire that ended the fighting of the Great War, signed in a railway carriage at Compiègne and in force at 11 a.m. Germany was beaten, though no Allied army stood on German soil.' },
    { id: 'coupon', m: 'coupon', title: 'The coupon election', date: 'December 1918',
      text: 'The coalition went to the country weeks after the Armistice. Its approved candidates got a letter of endorsement from the two coalition leaders, which a rival scornfully called the "coupon", after the ration coupon. Couponed candidates swept the board; those without were slaughtered.' },
    { id: 'amritsar', m: 'Jallianwala Bagh|Amritsar', title: 'The Amritsar massacre', date: '13 April 1919',
      text: 'In the Punjab city of Amritsar, General Dyer marched troops into the walled Jallianwala Bagh, where a large crowd had gathered, and fired without warning until the ammunition ran low. At least 379 people were killed by the official count, many more by Indian estimates. It turned millions of Indians against British rule.' },
    { id: 'afghan-1919', m: 'new Amir has sent his army', title: 'The Third Afghan War', date: 'May–August 1919',
      text: 'The new Amir of Afghanistan, Amanullah, sent troops across the border in May 1919, hoping the unrest in India would help him. The war was short, but the treaty that ended it gave Afghanistan full control of its own foreign affairs.' },
    { id: 'russia-1919', m: 'Archangel|White generals', title: 'Intervention in Russia', date: '1918–20',
      text: 'After the revolution, British, French, American and Japanese troops landed in Russia, at first to guard war stores, then to help the "White" armies fighting the Bolsheviks. War-weary Britain had little appetite for it, and the last British troops left Archangel in 1919.' },
    { id: 'irish-treaty', m: 'Black and Tans|Free State', title: 'The Irish war and the Treaty', date: '1919–22',
      text: 'Irish republicans fought a guerrilla war for independence from 1919. Britain answered with the Black and Tans and Auxiliaries, whose reprisals became notorious. The Treaty of December 1921 created the Irish Free State as a dominion; Northern Ireland stayed in the United Kingdom.' },
    { id: 'carlton-1922', m: 'summoned to the Carlton', title: 'The Carlton Club meeting', date: '19 October 1922',
      text: 'Conservative MPs met at the Carlton Club and voted 187 to 87 to fight the next election on their own, ending the coalition with Mr Lloyd Gwynne.' },
    { id: 'honours', m: 'honours for sale', title: 'Honours for sale', date: '1916–22',
      text: 'Under the coalition, knighthoods and peerages were openly sold through middlemen to fill party funds. The scandal broke in 1922 and led to a law against the trade in 1925.' },
    { id: 'gold', m: 'back on gold|back to gold|old parity|gold at its old value', title: 'The gold standard', date: '1925',
      text: 'Before 1914 the pound could be exchanged for a fixed weight of gold, at $4.86. Britain suspended this in the war. In 1925 the Chancellor put the pound back on gold at the old rate. Critics, Mr Kaine above all, warned it overvalued sterling and would mean wage cuts and unemployment.' },
    { id: 'general-strike', m: 'General Strike|May 1926', title: 'The General Strike', date: '4–12 May 1926',
      text: 'The coal owners locked out miners who would not accept lower pay and longer hours. The Trades Union Congress called out railwaymen, dockers, printers and others in support: about 1.7 million workers. Volunteers kept services running and the government ran its own paper. After nine days the TUC gave in; the miners fought on alone until the winter.' },
    { id: 'crash', m: 'Thursday morning they start to fall|the Crash', title: 'The Wall Street Crash', date: 'October 1929',
      text: 'After years of speculation on borrowed money, the New York stock market collapsed in the last week of October 1929, starting on "Black Thursday", 24 October. Fortunes vanished. The crash helped bring on the Great Depression, which spread around the world.' },
    { id: 'gandhi', m: 'Mr Gandhi|dominion status', title: 'Gandhi and dominion status', date: '1929–31',
      text: 'In 1929 the Viceroy promised India eventual dominion status, self-government like Canada\'s. Mohandas Gandhi led a campaign of civil disobedience, starting with the Salt March of 1930, and tens of thousands were jailed. In 1931 he was released to negotiate and came to London for a Round Table Conference.' },
    { id: 'qissa', m: 'Street of Storytellers|Red Shirts', title: 'The Red Shirts and the Qissa Khwani killings', date: '1930',
      text: 'Abdul Ghaffar Khan\'s Khudai Khidmatgar, the "Red Shirts", were a Pathan movement sworn to non-violence. On 23 April 1930, troops fired on a crowd in the Qissa Khwani Bazaar, the Street of Storytellers, in Peshawar. A platoon of the Garhwal Rifles refused to go in, and its men were court-martialled.' },
    { id: 'national-1931', m: 'National Government', title: 'The National Government', date: 'August 1931',
      text: 'In the financial crisis of 1931 the Labour Cabinet split over cutting unemployment benefit. Its Prime Minister, Mr MacDougal, formed a National Government with Conservatives and Liberals and was expelled from his own party. The National Government won a landslide that autumn.' },
    { id: 'nazis', m: 'largest party in the Reichstag', title: 'The rise of the Nazis', date: '1930–33',
      text: 'The Depression drove millions of Germans to the extremes. In July 1932 Hitler\'s Nazi Party won 37 per cent of the vote and became the largest party in the Reichstag. In January 1933 he was made Chancellor, and within months he had made himself dictator.' },
    { id: 'abyssinia', m: 'Abyssinia', title: 'The invasion of Abyssinia', date: 'October 1935',
      text: 'Mussolini\'s Italy invaded Abyssinia (Ethiopia), one of the last independent states in Africa, using poison gas. The League of Nations imposed weak sanctions. Britain and France then tried to buy Italy off with much of Abyssinia, and the League never recovered its authority.' },
    { id: 'abdication', m: 'Mrs Simpson', title: 'The Abdication', date: 'December 1936',
      text: 'King Edward VIII wished to marry Wallis Simpson, an American divorcing her second husband. The Church, the government and the Dominions would not accept her as Queen. The King chose to abdicate on 10 December 1936, after less than a year, and his brother became George VI.' },
    { id: 'glamour-boys', m: 'Glamour Boys', title: 'The Glamour Boys', date: '1938–39',
      text: 'The Whips\' sneering name for a group of younger Conservative MPs who gathered round the former Foreign Secretary after he resigned over appeasement in February 1938. They were critical, but cautious, and kept their distance from older and louder rebels.' },
    { id: 'munich', m: 'Munich|Sudetenland', title: 'The Munich Agreement', date: '30 September 1938',
      text: 'Hitler demanded the Sudetenland, the German-speaking border areas of Czechoslovakia, and threatened war. Britain, France, Germany and Italy agreed at Munich to hand it over; the Czechs were not at the table. The Prime Minister came home promising "peace for our time". Trenches were dug and gas masks given out while it hung in the balance.' },
    { id: 'by-elections-1938', m: 'Oxford by-election|Bridgwater by-election', title: 'The Munich by-elections', date: 'October–November 1938',
      text: 'Two by-elections were fought almost entirely on Munich. At Oxford the government candidate held the seat against an anti-Munich independent. At Bridgwater, a month later, an independent anti-Munich journalist won a safe Conservative seat.' },
    { id: 'poland-guarantee', m: 'guaranteed Poland', title: 'The guarantee to Poland', date: 'March 1939',
      text: 'In March 1939 Hitler broke the Munich promise and seized the rest of Czechoslovakia. Britain and France then promised to defend Poland if it was attacked: a guarantee that meant war when Germany invaded in September.' },
    { id: 'conscription-1939', m: 'conscription in peacetime', title: 'Conscription, 1939', date: 'April–May 1939',
      text: 'The Military Training Act called up men of twenty and twenty-one for six months\' training, the first peacetime conscription in British history. Labour and the Liberals voted against it.' },
    { id: 'poland-1939', m: 'invaded Poland', title: 'The invasion of Poland', date: '1 September 1939',
      text: 'Germany invaded Poland at dawn on 1 September 1939. For two days the British government hesitated while it tried to coordinate with France, and the Commons grew angry. Britain declared war on 3 September.' },
    { id: 'phoney-war', m: 'war has begun with nothing happening', title: 'The Phoney War', date: 'September 1939 – April 1940',
      text: 'After Poland fell, almost nothing happened on land in the West for seven months. The expected bombing did not come, evacuated children drifted home, and Americans called it the "phoney war".' },
    { id: 'rationing', m: 'Rationing|ration book', title: 'Rationing', date: 'from January 1940',
      text: 'Food rationing began in January 1940 with bacon, butter and sugar, and soon took in meat, tea, fats, cheese and more. Every household registered with one shopkeeper and handed over coupons from its ration books. Some rationing went on until 1954.' },
    { id: 'norway', m: 'seized Norway|Trondheim|Two days of debate on Norway|Norway fiasco', title: 'The Norway campaign and debate', date: 'April–May 1940',
      text: 'Germany seized Denmark and Norway in April 1940. British landings to take back Trondheim and Narvik went badly. In the Commons debate of 7–8 May, a Tory MP told the government "in the name of God, go", quoting Cromwell. The government\'s majority fell from about 200 to 81, and the Prime Minister resigned two days later.' },
    { id: 'dunkirk', m: 'Dunkirk', title: 'Dunkirk', date: '26 May – 4 June 1940',
      text: 'The German breakthrough in France trapped the British army against the Channel. From the beaches and harbour of Dunkirk, warships and hundreds of small boats carried about 338,000 British and French soldiers back to England. They left almost all their guns and vehicles behind.' },
    { id: 'sedan', m: 'Sedan', title: 'The fall of France', date: 'May–June 1940',
      text: 'On 13 May 1940 German armour broke through the French line at Sedan, in the Ardennes, and raced to the Channel. Paris fell on 14 June, and France signed an armistice on 22 June. Britain and its Empire fought on alone.' },
    { id: 'mers-el-kebir', m: 'Mers-el-Kébir', title: 'Mers-el-Kébir', date: '3 July 1940',
      text: 'Fearing the French fleet would fall to Germany, Britain gave the French squadron at Mers-el-Kébir, near Oran, a choice: join, sail away, scuttle, or be sunk. The French refused, and British ships opened fire. Nearly 1,300 French sailors were killed.' },
    { id: 'blitz', m: 'Blitz|bombers have come to the East End|The bombers come every night now', title: 'The Blitz', date: 'September 1940 – May 1941',
      text: 'The German night-bombing campaign against British cities. London was bombed on 56 of 57 nights from 7 September 1940; Coventry, Liverpool, Plymouth, Glasgow and many others were hit hard. About 43,000 civilians were killed.' },
    { id: 'warden', m: 'air-raid warden', title: 'ARP wardens', date: '1938–45',
      text: 'Air Raid Precautions wardens, most of them part-time volunteers, enforced the blackout, guided people to shelters, reported bomb damage and were often first at an incident. About one in six was a woman.' },
    { id: 'home-guard', m: 'Home Guard', title: 'The Home Guard', date: '1940–44',
      text: 'Raised in May 1940 as the Local Defence Volunteers, from men too old, too young or too needed at work for the forces. At first they drilled with shotguns and broom handles. By 1943 there were 1.7 million of them, guarding the coast, factories and railways.' },
    { id: 'fire-watch', m: 'fire-watcher', title: 'Fire-watching', date: 'from January 1941',
      text: 'After the great fire raid on the City of London at the end of December 1940, fire-watching became compulsory. Men up to sixty had to spend nights on roofs ready to put out incendiary bombs with sand and stirrup pumps.' },
    { id: 'coventry', m: 'Coventry', title: 'Coventry', date: '14 November 1940',
      text: 'A single night raid destroyed much of the centre of Coventry, including its medieval cathedral, and killed about 568 people. The Germans coined a word for it: to "coventrate" a city.' },
    { id: 'barbarossa', m: 'invaded Russia', title: 'Operation Barbarossa', date: '22 June 1941',
      text: 'Germany invaded the Soviet Union with more than three million men along a front from the Baltic to the Black Sea, breaking the pact Hitler and Stalin had signed in 1939. It became the largest and deadliest campaign in history.' },
    { id: 'commandos', m: 'commandos', title: 'The commandos', date: 'from 1940',
      text: 'Volunteer raiding units formed after Dunkirk to strike at the occupied coast. They trained hard in the Scottish highlands and were used for raids in Norway, France and the Mediterranean. The service chiefs often resented them as a drain on men and ships.' },
    { id: 'truce', m: 'under the truce', title: 'The electoral truce', date: '1939–45',
      text: 'Early in the war the main parties agreed not to fight each other at by-elections. When a seat fell vacant, the party that held it named the new Member, and the others stood aside. Independents were free to stand, and from 1941 some began to win.' },
    { id: 'pearl-harbor', m: 'Pearl Harbor|America is in the war', title: 'Pearl Harbor', date: '7 December 1941',
      text: 'Japanese carrier aircraft attacked the United States Pacific Fleet at Pearl Harbor in Hawaii, killing about 2,400 Americans. Japan attacked Malaya and Hong Kong the same day. Germany declared war on America four days later, and the war became a world war.' },
    { id: 'singapore', m: 'Singapore', title: 'The fall of Singapore', date: '15 February 1942',
      text: 'The great naval base at Singapore was thought impregnable from the sea. The Japanese came down the Malay peninsula by land instead, and in a week of fighting on the island the garrison surrendered. About 80,000 British, Indian and Australian troops went into captivity, the worst defeat in British history.' },
    { id: 'changi', m: 'Changi', title: 'Changi', date: '1942–45',
      text: 'Changi, at the eastern end of Singapore island, held prisoners of war in its barracks and civilian internees in its gaol. Food was rice and little else; beri-beri, dysentery and cruelty took a steady toll.' },
    { id: 'burma-railway', m: 'railway through the jungle', title: 'The Burma Railway', date: '1942–43',
      text: 'The Japanese built a railway 258 miles long through the jungle from Thailand to Burma using about 60,000 Allied prisoners and far more Asian labourers. About 12,000 prisoners and perhaps 90,000 labourers died of disease, starvation and beatings. It was called the Death Railway.' },
    { id: 'bomber-command', m: 'Bomber Command|dehoused', title: 'Area bombing', date: '1942–45',
      text: 'A 1941 report showed that most British bombers were not even finding their target cities at night. From 1942 Bomber Command switched to "area bombing": attacking whole cities, aiming at the homes and morale of German workers. Hundreds of thousands of German civilians were killed by the end of the war.' },
    { id: 'tobruk', m: 'Tobruk', title: 'The fall of Tobruk', date: '21 June 1942',
      text: 'The Libyan port of Tobruk had held out through a long siege in 1941. In June 1942 Rommel took it in a day, with about 33,000 prisoners. The news reached the Prime Minister while he was with the President in Washington.' },
    { id: 'censure', m: 'vote of no confidence|censure motion', title: 'The censure motion', date: 'July 1942',
      text: 'After Tobruk, a senior Conservative moved a motion of no confidence in the central direction of the war. Its seconder undermined it by saying the Prime Minister should have more power, not less. The government won by 475 to 25.' },
    { id: 'beveridge', m: 'report on social insurance|inquiry into social insurance|Beverley Report', title: 'The Beveridge Report', date: 'December 1942',
      text: 'A report by Sir William Beverley proposing social insurance for everyone, "from the cradle to the grave", against want, disease, ignorance, squalor and idleness. It sold more than 600,000 copies. It became the blueprint for the post-war welfare state.' },
    { id: 'bengal', m: 'famine in Bengal|Bengal is starving', title: 'The Bengal famine', date: '1943',
      text: 'A cyclone, the loss of Burma\'s rice to Japan, wartime inflation, hoarding and the government\'s slowness to act brought famine to Bengal. Between one and three million people died; estimates still differ. Requests for grain imports collided with the shipping needs of the war, and the response from London was slow.' },
    { id: 'tito', m: 'Tito|Chetniks|Partisans', title: 'Tito and the Partisans', date: '1941–45',
      text: 'Occupied Yugoslavia had two resistance movements: the royalist Chetniks of Draža Mihailović and the Communist Partisans of Josip Broz, called Tito. British liaison officers were parachuted in to report which was really fighting the Germans. In 1943 Britain switched its support to Tito.' },
    { id: 'casablanca', m: 'Casablanca', title: 'The Casablanca Conference', date: 'January 1943',
      text: 'The Prime Minister and President Roosevelt met at Casablanca in Morocco to plan the next stage of the war, and announced that they would accept nothing short of the enemy\'s unconditional surrender.' },
    { id: 'v1', m: 'flying bombs', title: 'The flying bombs', date: 'June 1944 – March 1945',
      text: 'The V-1, a pilotless jet-propelled bomb, began falling on London a week after D-Day. Londoners called them doodlebugs. When the engine cut out, it dived. One hit the Guards Chapel in Wellington Barracks during a Sunday service, killing 121 people. About 6,000 people were killed by V-1s.' },
    { id: 'v2', m: 'Peenemünde', title: 'The V-2 rocket', date: '1944–45',
      text: 'The world\'s first long-range ballistic missile, developed at Peenemünde on the Baltic coast. It fell faster than sound, so there was no warning and no defence. From September 1944 about 1,100 hit England, killing some 2,700 people.' },
    { id: 'percentages', m: 'half-sheet of paper', title: 'The percentages agreement', date: 'October 1944',
      text: 'In Moscow, the Prime Minister passed Stalin a note dividing influence in the Balkans by percentages. Stalin ticked it with a blue pencil. It was never a formal treaty, and Poland was not on the paper.' },
    { id: 've-day', m: 'Germany has surrendered', title: 'VE Day', date: '8 May 1945',
      text: 'Victory in Europe Day, after Germany\'s unconditional surrender. Crowds filled Whitehall, Trafalgar Square and the Mall; the King and Queen came out on the balcony of Buckingham Palace again and again, and the war ministers waved from the Ministry of Health.' },
    { id: 'election-1945', m: 'soldiers\' ballots|The votes are counted|ten years since the last one|soldiers\' votes come home', title: 'The 1945 election', date: 'July 1945',
      text: 'Polling was on 5 July 1945, but the count waited three weeks for the votes of servicemen abroad. Labour won 393 seats, a majority of 146, on promises of jobs, homes and a National Health Service.' },
    { id: 'gestapo', m: 'police state|political police', title: 'The "Gestapo" broadcast', date: '4 June 1945',
      text: 'In his first broadcast of the 1945 campaign, the Conservative leader said a socialist government would need "some form of Gestapo" to enforce its plans. Labour\'s leader answered calmly the next night. It is often thought to have cost the Conservatives votes.' },
    { id: 'iron-curtain', m: 'a line has come down across Europe', title: 'The "Iron Curtain" speech', date: '5 March 1946',
      text: 'At Westminster College in Fulton, Missouri, with President Truman on the platform, the former Prime Minister warned that an iron curtain had descended across Europe from Stettin on the Baltic to Trieste on the Adriatic. Many Americans thought it warmongering at the time.' },
    { id: 'winter-1947', m: 'worst winter in living memory|A frozen winter', title: 'The winter of 1947', date: 'January–March 1947',
      text: 'Weeks of snow and frost froze coal stocks at the pits and stopped the trains. Power stations shut down, factories closed, and two million people were thrown out of work for a time. The fuel minister had promised there would be no crisis.' },
    { id: 'india-1947', m: 'leave India by June 1948|leave by June 1948|partitioned', title: 'Independence and Partition', date: 'August 1947',
      text: 'In February 1947 the government announced that Britain would leave India by June 1948. The new Viceroy brought the date forward to 15 August 1947 and divided the country into India and Pakistan. Up to a million people were killed and some fifteen million fled their homes.' },
    { id: 'schuman', m: 'pooling the coal and steel|pooling Europe\'s coal and steel', title: 'The Schuman Plan', date: 'May 1950',
      text: 'The French Foreign Minister, Robert Schuman, proposed putting French and German coal and steel under a common High Authority, so that war between them would become impossible. Britain refused to join the talks. The European Coal and Steel Community that followed was the seed of the European Union.' },
    { id: 'teeth', m: 'teeth and spectacles', title: 'The health charges', date: 'April 1951',
      text: 'To pay for rearmament during the Korean War, the Labour Chancellor brought in charges for NHS false teeth and spectacles. The Minister of Labour, Mr Bowen, and two others resigned in protest, and the party split.' },
    // ── places, institutions and smaller episodes ──
    { id: 'britannia', m: 'HMS Britannia', title: 'HMS Britannia', date: '1863–1905',
      text: 'The Royal Navy trained its officer cadets aboard an old wooden warship moored in the river Dart at Dartmouth. Boys joined at twelve or thirteen, and their places in the passing-out examinations fixed their seniority for the rest of their careers.' },
    { id: 'harrow', m: 'Harrow', title: 'Harrow School', date: '',
      text: 'One of the great public schools, on a hill north-west of London, with Eton its chief rival. Its Army Class prepared boys for Sandhurst and Woolwich. Harrow has produced more Prime Ministers than any school but Eton.' },
    { id: 'slave-dhows', m: 'slave dhows', title: 'The anti-slavery patrols', date: '1870s–90s',
      text: 'Britain had abolished slavery in its empire in 1833 and used the Navy to suppress the trade. Off East Africa, ships\' boats hunted Arab dhows carrying captives from the mainland to Zanzibar and Arabia. Freed captives were landed at missions, where their fate was often uncertain.' },
    { id: 'shearers', m: 'shearers have struck', title: 'The Queensland shearers\' strike', date: '1891',
      text: 'Shearers in Queensland struck against pastoralists\' contracts that undermined their union. The colonial government sent troops, police and artillery, and strike leaders were jailed for conspiracy. The defeat helped persuade Australian unions to found their own political party, Labor.' },
    { id: 'balliol', m: 'Balliol', title: 'Balliol and Greats', date: '',
      text: 'Balliol College, Oxford, under its Master Benjamin Jowett, set out to train the men who would govern Britain and the Empire. "Greats" was the four-year course in Latin and Greek literature, ancient history and philosophy, the most prestigious degree in Oxford.' },
    { id: 'all-souls', m: 'All Souls', title: 'All Souls College', date: '',
      text: 'An Oxford college with no undergraduates. Each year it elects one or two young graduates to fellowships by a famously hard examination. A fellowship brought rooms, dinners and a small income, and its fellows filled the higher ranks of politics, the law and The Times.' },
    { id: 'transvaal', m: 'Transvaal', title: 'The Transvaal question', date: '1890s',
      text: 'The Transvaal, a Boer republic, held the richest gold field in the world on the Witwatersrand. Thousands of foreign miners, mostly British, flooded in; the Boers denied them the vote. Britain pressed their cause, the Boers armed, and by 1899 the two sides were drifting towards war.' },
    { id: 'macedonia', m: 'Ottoman Macedonia', title: 'Macedonia under the Ottomans', date: '1890s–1912',
      text: 'Macedonia was still a province of the Ottoman Empire, claimed by Bulgaria, Greece and Serbia alike. Armed bands of each nation fought the Turks and each other in the hills. The struggle ended only with the Balkan Wars of 1912–13.' },
    { id: 'coterie', m: 'the Coterie', title: 'The Coterie', date: 'about 1908–14',
      text: 'A set of clever, rich and reckless young men and women in Edwardian London who gambled, drank, wrote verse and scandalised their parents. Many of the young men were killed in the Great War.' },
    { id: 'jirga', m: 'jirga|malik|Political Agent', title: 'Maliks and jirgas', date: '',
      text: 'Among the Pathan tribes a malik was a headman, and a jirga a council of elders that settled disputes and made terms. British political officers dealt with the tribes through the maliks, paying allowances and fining whole clans for raids.' },
    { id: 'mahdi', m: 'Mahdi', title: 'The Mahdi', date: '1881–98',
      text: 'Muhammad Ahmad proclaimed himself the Mahdi, the redeemer of Islam, in the Sudan in 1881, and his rising drove out the Egyptian government and killed Gordon. He died months after taking Khartoum. After Omdurman, Kitchener had his tomb destroyed, which caused outrage in Britain.' },
    { id: 'tithes', m: 'Tithes Bill|tithes', title: 'The Clerical Tithes Bill', date: '1899',
      text: 'A Conservative Bill to relieve Church of England clergy of part of the local rates on their tithe income. Nonconformists, strong in Lancashire, saw it as a handout to the established Church from their own pockets.' },
    { id: 'state-model-school', m: 'school in Pretoria', title: 'The State Model School', date: '1899',
      text: 'A school building in Pretoria used by the Boers to hold captured British officers. On 12 December 1899 one prisoner climbed the wall by the latrine and escaped, reaching Portuguese East Africa by goods train.' },
    { id: 'new-territories', m: 'north of Hong Kong', title: 'The New Territories', date: '1898–99',
      text: 'In 1898 Britain leased the land north of Kowloon from China for ninety-nine years. When British forces came to take it over in April 1899, armed villagers resisted for six days before they were dispersed.' },
    { id: 'enteric', m: 'enteric fever', title: 'Enteric fever', date: '',
      text: 'Typhoid, spread by bad water. In the Boer War it killed more British soldiers than Boer bullets did: about 8,000 against roughly 6,000 killed in action. Bloemfontein became a vast fever hospital in 1900.' },
    { id: 'khyber', m: 'Khyber|Afridi', title: 'The Khyber and the Afridis', date: '',
      text: 'The Khyber Pass, the main road from Peshawar to Kabul, ran through the country of the Afridi tribes. The British paid them allowances to keep it open and raised a militia, the Khyber Rifles, from among them. In 1897 the Afridis rose and the militia posts fell.' },
    { id: 'gangway', m: 'below the gangway|across the floor', title: 'Gangway and floor', date: '',
      text: 'In the Commons, a gangway crosses the benches on each side. Ministers and loyalists sit above it; independent spirits and rebels sit below it. To "cross the floor" is to leave your party and sit on the other side of the House.' },
    { id: 'lobby', m: 'Members\' Lobby', title: 'The Members\' Lobby', date: '',
      text: 'The hall outside the Commons chamber where Members meet ministers, Whips and accredited journalists. Much of the real business of Parliament, the deals, the gossip and the threats, is done here standing up.' },
    { id: 'whips', m: 'Chief Whip|the Whips', title: 'The Whips', date: '',
      text: 'Party managers who make sure Members turn up and vote as the leaders want, with favours for the loyal and pressure on the rest. The Chief Whip knows every Member\'s weaknesses. Their written summons to vote, underlined three times for an important division, is also called a whip.' },
    { id: 'embankment', m: 'the Embankment', title: 'The Victoria Embankment', date: 'opened 1870',
      text: 'The great river wall and road along the Thames from Westminster to Blackfriars, built over a new sewer, lit by cast-iron dolphin lamps and lined with plane trees. The natural walk home for Members when the House rose late.' },
    { id: 'simla', m: 'Simla', title: 'Simla', date: '',
      text: 'The hill station in the Himalayan foothills where the government of India moved every summer to escape the heat of the plains. Famous for its balls, amateur theatricals, flirtations and intrigues.' },
    { id: 'zakka', m: 'Zakka Khel', title: 'The Bazar valley expedition', date: 'February 1908',
      text: 'After a run of raids by the Zakka Khel Afridis, even into Peshawar, General Sir James Willcocks led a punitive column into the Bazar valley. It was over in about a fortnight, and the clans paid fines and gave pledges.' },
    { id: 'landslide-1906', m: 'worst defeat in their history|by thousands in 1906', title: 'The Liberal landslide', date: 'January 1906',
      text: 'At the general election of 1906 the Liberals won about 400 seats and the Conservatives fell to 157. Twenty-nine Labour Members were elected too, the start of the Labour Party in Parliament.' },
    { id: 'young-turks', m: 'Young Turk', title: 'The Young Turks', date: '1908–18',
      text: 'Nationalist army officers and reformers who took power in the Ottoman Empire after 1908 and ruled it through the war. They took the Empire into the war on Germany\'s side in 1914.' },
    { id: 'kabul-1915', m: 'Niedermayer', title: 'The German mission to Kabul', date: '1915–16',
      text: 'A German and Turkish mission led by Oskar von Niedermayer and Werner Otto von Hentig crossed Persia in 1915 and reached Kabul, hoping to bring Afghanistan into the war and raise the frontier tribes. The Amir received them courteously and stayed neutral.' },
    { id: 'spin', m: 'fall into a spin', title: 'The spin', date: '1910s',
      text: 'Early aircraft that stalled could fall into a spin, which killed many pilots because nobody knew how to recover from it. During the war scientists at the Royal Aircraft Factory at Farnborough worked out the theory and tested it in the air themselves.' },
    { id: 'swiss-internment', m: 'neutral Switzerland', title: 'Internment in Switzerland', date: '1916–18',
      text: 'By agreement through the Red Cross, some sick and long-held prisoners of war on both sides were moved from camps to internment in neutral Switzerland, where they lived in hotels under guard until the war ended.' },
    { id: 'salonika', m: 'Salonika', title: 'The Salonika front', date: '1915–18',
      text: 'An Allied army landed at Salonika in Greece in 1915 to help Serbia, too late. It then sat for three years facing the Bulgarians across the mountains, suffering more from malaria than from the enemy.' },
    { id: 'hundred-days', m: 'August 1918', title: 'The Hundred Days', date: 'August–November 1918',
      text: 'From 8 August 1918 the Allied armies attacked again and again, breaking the German lines and crossing canals and rivers under fire. The war of movement had returned, and it was costly to the end.' },
    { id: 'prohibitionist', m: 'Prohibitionist', title: 'The Dundee Prohibitionist', date: '1908–31',
      text: 'Dundee, a two-member seat, was fought for years by a candidate who wanted to ban alcohol outright. He lost again and again, and kept coming back.' },
    { id: 'razmak', m: 'Razmak|Waziristan', title: 'Waziristan and Razmak', date: '1919–23',
      text: 'After a hard campaign against the Mahsud and Wazir tribes, the government of India decided to occupy central Waziristan for good. Roads were driven through the hills and a large garrison was built at Razmak, high in the tribal country.' },
    { id: 'abbey-1924', m: 'Abbey division', title: 'The Westminster Abbey by-election', date: 'March 1924',
      text: 'A famous by-election in the seat that contains Parliament itself. An independent anti-socialist ran against the official Conservative with the support of much of the press and a crowd of volunteer helpers, and lost by just 43 votes.' },
    { id: 'constitutionalist', m: 'Constitutionalist', title: 'The Constitutionalists', date: '1924',
      text: 'A handful of former Liberals who stood in 1924 with Conservative support and without Conservative opponents, as a halfway house on the road to joining the Tories.' },
    { id: 'bankrupt', m: 'petition in bankruptcy|undischarged bankrupt|trustee in bankruptcy', title: 'Bankrupt Members', date: '',
      text: 'A man adjudged bankrupt could not sit or vote in the House of Commons, and if the bankruptcy stood his seat was declared vacant. Until he was discharged by the court, his earnings went to a trustee to pay his creditors.' },
    { id: 'india-bill', m: 'India Bill', title: 'The Government of India Act', date: '1935',
      text: 'The longest Act Parliament had ever passed. It gave the Indian provinces elected self-government and planned an all-India federation. Conservative diehards fought it clause by clause for two years. The federation never came into being.' },
    { id: 'radar', m: 'radio direction-finding', title: 'Radio direction-finding', date: '1935',
      text: 'What later became known as radar. In February 1935 a Scottish radio scientist showed that radio waves bounced off an aircraft could be detected miles away. An Air Ministry committee of scientists backed it, and a chain of stations was built round the coast in time for 1940.' },
    { id: 'luftwaffe-figures', m: 'German aircraft factories', title: 'The German air figures', date: '1934–36',
      text: 'Germany was building an air force in secret, against the Versailles treaty, then openly from 1935. How big it was, and how fast it was growing, was one of the great arguments of the decade, and the government\'s own figures were challenged in the House with leaked numbers.' },
    { id: 'division', m: 'The division|forced a division', title: 'A division', date: '',
      text: 'A formal vote in the House. Members walk through the Aye or No lobbies on either side of the chamber and are counted by tellers. How a Member votes is published, and remembered.' },
    { id: 'war-cabinet', m: 'War Cabinet', title: 'The War Cabinet', date: '1939–45',
      text: 'A small inner Cabinet of a handful of senior ministers that ran the war, meeting almost daily. The service chiefs attended to advise. A seat in it was the real measure of power.' },
    { id: 'ninth-may', m: 'Four men in the Cabinet Room', title: 'The meeting of 9 May 1940', date: '9 May 1940',
      text: 'After the Norway debate the Prime Minister knew he could not go on without Labour, and Labour would not serve under him. He called in the two possible successors and the Chief Whip to settle who should take his place. What was said is still argued over by historians.' },
    { id: 'treachery', m: 'neutral legation', title: 'Spies in wartime London', date: '1939–45',
      text: 'German intelligence tried to recruit sympathisers in Britain, sometimes through neutral diplomats. The Treachery Act of 1940 made helping the enemy a capital crime; fifteen men were hanged under it and one shot. Most German agents who landed were caught and many were turned to work for MI5.' },
    { id: 'carlton-club', m: 'The Carlton|the Carlton', title: 'The Carlton Club', date: 'founded 1832',
      text: 'The Conservative Party\'s club, on Pall Mall, where Tory Members dined, plotted and read the papers. Membership was a sign of belonging. On the night of 14 October 1940 a German bomb wrecked the building while members were at dinner; no one was killed.' },
    { id: 'by-election', m: 'by-election', title: 'By-elections', date: '',
      text: 'When a Member dies, resigns or is made a peer, his seat is filled by a by-election in that one constituency. Until 1926 a Member appointed to the Cabinet also had to fight his seat again. By-elections are the country\'s way of telling a government what it thinks between general elections.' },
    // ── The Quiet Major ──
    { id: 'dock-1889', m: 'London docks have stopped|sixpence an hour', title: 'The Great Dock Strike', date: 'August–September 1889',
      text: 'Casual dockers, hired by the half-day at the dock gates, struck for sixpence an hour, "the docker\'s tanner", and a minimum of four hours\' work. The port of London stood still for five weeks. Cardinal Manning mediated, Australian unions sent £30,000, and the men won. It launched the "new unionism" of unskilled workers.' },
    { id: 'armenians', m: 'massacres of Armenian', title: 'The Armenian massacres', date: '1894–96',
      text: 'Under Sultan Abdul Hamid II, Ottoman troops and irregulars killed Armenian Christians in town after town of eastern Anatolia and in Constantinople itself. Estimates run from 100,000 to 300,000 dead. British opinion was outraged, but the Great Powers could not agree to act.' },
    { id: 'jubilee', m: 'Sixty years of the Queen', title: 'The Diamond Jubilee', date: '22 June 1897',
      text: 'Queen Victoria\'s sixty years on the throne were celebrated as a festival of Empire. Troops from India, Canada, Australia, Africa, the Caribbean and the Far East marched in the procession to St Paul\'s, and bonfires were lit on hills across the country.' },
    { id: 'haileybury', m: 'Haileybury was built', title: 'Haileybury', date: '',
      text: 'The East India Company\'s college at Haileybury in Hertfordshire trained young men for the Indian civil service until 1858. It reopened in 1862 as a public school, and kept its imperial and military tradition: many of its boys went on to the Army and to India.' },
    { id: 'ilp', m: 'Independent Labour Party|the ILP', title: 'The Independent Labour Party', date: 'founded 1893',
      text: 'A socialist party founded in Bradford in 1893, which helped create the Labour Party in 1900 and stayed inside it as its most idealistic and argumentative wing. Its members spoke at street corners, ran Sunday schools and opposed the Great War.' },
    { id: 'fabians', m: 'the Fabians|Fabian Society', title: 'The Fabian Society', date: 'founded 1884',
      text: 'A society of middle-class socialists who believed in gradual reform through research, pamphlets and persuading people in power, rather than revolution. Its leading lights wrote the tracts, sat on commissions and later helped write Labour\'s policies.' },
    { id: 'minority-report', m: 'Minority Report', title: 'The Minority Report', date: '1909',
      text: 'The Royal Commission on the Poor Laws split in 1909. The majority wanted to reform the workhouse system; a minority, led by Beatrice Webber, wanted to abolish it and replace it with public services for health, unemployment and old age. Their campaign failed at the time but shaped the welfare state.' },
    { id: 'toynbee', m: 'Toynbee Hall|Nobody in Whitechapel', title: 'Toynbee Hall', date: 'founded 1884',
      text: 'A "settlement" in Whitechapel where young university men lived among the East End poor, ran clubs, classes and legal advice, and studied poverty at first hand. Many future reformers and civil servants passed through it.' },
    { id: 'national-insurance', m: 'National Insurance Act', title: 'The National Insurance Act', date: '1911',
      text: 'Insurance against sickness for most workers, and against unemployment in a few trades, paid for by weekly stamps: fourpence from the worker, threepence from the employer and twopence from the state, "ninepence for fourpence". Doctors, friendly societies and many workers opposed it at first.' },
    { id: 'tribunals', m: 'Conscription has come|local tribunal|Military Service Act has come', title: 'Conscription and the tribunals', date: 'from 1916',
      text: 'The Military Service Acts of 1916 conscripted single and then married men. Local tribunals heard claims for exemption, including from about 16,000 conscientious objectors. Some accepted non-combatant work; about 6,000 were imprisoned, and the "absolutists" who refused all service were jailed again and again.' },
    { id: 'kut', m: 'relieve the army starving in Kut|Kut', title: 'Kut and Hanna', date: '1915–16',
      text: 'A British and Indian army that had advanced up the Tigris towards Baghdad was besieged by the Turks at Kut-al-Amara from December 1915. Relief forces attacked the Turkish lines at Hanna and beyond again and again and failed. Kut surrendered on 29 April 1916, and thousands of its men died in captivity.' },
    { id: 'poplar', m: 'Poplar has refused|Poplar', title: 'The Poplar rates rebellion', date: '1921',
      text: 'Poor East End boroughs paid for their own poor relief out of local rates, while rich boroughs paid little. In 1921 Poplar\'s Labour council refused to collect the money it owed to London-wide bodies. Thirty councillors were jailed for six weeks. The government gave way and shared the cost of relief across London.' },
    { id: 'lascars', m: 'lascars', title: 'Lascars', date: '',
      text: 'Indian, Arab and East African seamen employed on British ships, often on lower pay than British sailors. Limehouse, near the docks, had boarding houses for them and one of London\'s first Chinese communities.' },
    { id: 'frost-1895', m: 'hardest frost in living memory', title: 'The great frost of 1895', date: 'February 1895',
      text: 'Weeks of severe frost froze ponds, canals and parts of the Thames, where ice floes jammed the river. Work stopped for watermen, dockers, builders and coal-heavers, all paid by the day. Relief funds and soup kitchens were opened across London.' },
    { id: 'school-missions', m: 'boys\' club in Stepney', title: 'School missions and boys\' clubs', date: '1880s–1930s',
      text: 'Many public schools and colleges ran a "mission" or club in a poor district of London, where old boys volunteered in the evenings with boxing, football, savings banks and summer camps for working boys. For a number of future politicians it was their first sight of real poverty.' },
    { id: 'councils-1919', m: 'Labour has swept the Stepney', title: 'Labour takes the town halls', date: 'November 1919',
      text: 'In the London borough elections of 1919 Labour won control of about a dozen boroughs, most of them in the East End, and began using local government to improve housing, health and poor relief.' },
    { id: 'zinoviev', m: 'Zinoviev', title: 'The Zinoviev letter', date: 'October 1924',
      text: 'A letter, said to be from Grigory Zinoviev of the Communist International, urging British Communists to stir up revolution, published by the Daily Mail four days before the 1924 election. It helped the Conservatives paint Labour as soft on Moscow. Most historians now think it a forgery.' },
    { id: 'simon-commission', m: 'a commission to decide India', title: 'The Simon Commission', date: '1927–30',
      text: 'A Parliamentary commission of seven British members sent to report on India\'s constitution. Because it had no Indian members, the Indian National Congress and others boycotted it, greeting it with black flags. Its report was overtaken by the Round Table Conferences.' },
    { id: 'mosley-memo', m: 'Moseby, a brilliant', title: 'The Moseby memorandum', date: '1930',
      text: 'A young Labour minister proposed tackling unemployment with public works, protective tariffs, cheap credit and early retirement pensions. The Cabinet and the Treasury rejected it. He resigned in May 1930, left Labour to found the New Party, and went on to lead British fascism.' },
    { id: 'means-test', m: 'means test', title: 'The means test', date: 'from 1931',
      text: 'From 1931 the long-term unemployed had to prove need to get relief. Officials visited homes and counted the family\'s savings, furniture and the earnings of sons and daughters. It was bitterly hated, and broke up many households.' },
    { id: 'intl-brigades', m: 'International Brigades', title: 'The International Brigades', date: '1936–38',
      text: 'Volunteers from more than fifty countries who went to fight for the Spanish Republic against Franco\'s rebels. About 2,500 came from Britain and Ireland, many of them unemployed workers and Communists; over 500 were killed. Britain\'s policy of non-intervention barred arms sales to both sides.' },
    { id: 'rhineland', m: 'marched into the Rhineland', title: 'The Rhineland', date: '7 March 1936',
      text: 'Hitler sent troops into the Rhineland, the strip of Germany along the French border that the Versailles and Locarno treaties had made a demilitarised zone. France and Britain protested and did nothing.' },
    { id: 'popular-front', m: 'Popular Front', title: 'The Popular Front', date: '1936–39',
      text: 'The idea, borrowed from France and Spain, of an alliance of Labour, Liberals and Communists against fascism and appeasement. Labour\'s leaders refused, fearing Communist infiltration. A senior Labour lawyer who campaigned for it anyway was expelled in January 1939, and several left-wing MPs followed.' },
    { id: 'leader-opposition', m: 'leader of the Opposition|Leader of the Opposition', title: 'Leader of the Opposition', date: 'from 1937 a paid office',
      text: 'The leader of the largest party not in government. The Ministers of the Crown Act 1937 gave the post a salary for the first time, which made it an official part of the constitution rather than a party job.' },
    { id: 'west-1940', m: 'attacked in the West at dawn', title: 'The German offensive in the West', date: '10 May 1940',
      text: 'After eight months of the Phoney War, Germany invaded the Netherlands, Belgium and Luxembourg at dawn on 10 May 1940, and broke through the French line at Sedan three days later. The same evening Chamberlain resigned and a coalition government was formed.' },
    { id: 'manpower', m: 'manpower of the nation', title: 'The direction of labour', date: 'from May 1940',
      text: 'The Emergency Powers (Defence) Act of 22 May 1940 gave the government power over every person and all property in the country. The new Minister of Labour, a trade union leader brought straight into the Cabinet, could direct men and later women into essential work, control wages and ban strikes.' },
    { id: 'tilbury', m: 'Tilbury shelter', title: 'The Tilbury shelter', date: '1940–41',
      text: 'A huge goods depot under the railway arches off Commercial Road in Stepney. During the Blitz up to fourteen thousand people a night crowded into it, among the cargo, with almost no lavatories. It became a byword for the state of East End shelters.' },
    { id: 'lord-president', m: 'committees of the home front|overrules committees', title: 'Running the home front', date: '1940–45',
      text: 'While the Prime Minister ran the war, home affairs were handled by Cabinet committees, above all the Lord President\'s Committee, which settled food, fuel, manpower and the economy. Labour ministers chaired many of them, and earned a reputation for competence that helped them win in 1945.' },
    { id: 'quit-india', m: 'quit India', title: 'Quit India', date: 'August 1942',
      text: 'On 8 August 1942 the Indian National Congress demanded that Britain leave India immediately, backed by mass civil disobedience. Gandhi, Nehru and the Congress leaders were arrested the next morning and held for most of the war. The rising that followed was put down by force; about a thousand people were killed.' },
    { id: 'deputy-pm', m: 'Deputy Prime Minister', title: 'Deputy Prime Minister', date: 'from February 1942',
      text: 'Not a legal office but a title. It was first used formally in February 1942 for the Labour leader in the wartime coalition, who chaired the Cabinet when the Prime Minister was abroad.' },
    { id: 'palace', m: 'go straight to the Palace', title: 'Kissing hands', date: 'convention',
      text: 'When a government falls, the King sends for the person he thinks can command a majority in the Commons. Labour\'s rules said nothing about whether its MPs must first elect a leader before he went, which is why the timing mattered so much in July 1945.' },
    { id: 'nhs', m: 'building a health service|National Health Service begins|From midnight every hospital', title: 'The National Health Service', date: '5 July 1948',
      text: 'A health service free at the point of use for everyone, paid for from taxation. Hospitals were nationalised; GPs, after a long fight by the British Medical Association, joined as contractors. In its first year demand for spectacles, dentures and prescriptions far exceeded the estimates.' },
    { id: 'lend-lease', m: 'Lend-Lease', title: 'Lend-Lease', date: 'March 1941 – August 1945',
      text: 'The American programme that supplied Britain with food, oil, weapons and ships on credit during the war. President Truman ended it abruptly on 21 August 1945, days after Japan surrendered, leaving Britain without the means to pay for its imports.' },
    { id: 'convertibility', m: 'freely changed into dollars|convertibility clause', title: 'The American loan and convertibility', date: '1945–47',
      text: 'The United States lent Britain $3.75 billion in December 1945, on condition that sterling be made freely convertible into dollars within a year of the loan taking effect. When convertibility came on 15 July 1947, holders of pounds rushed to change them, and the reserves drained so fast that it was suspended five weeks later.' },
    { id: 'national-insurance-1946', m: 'National Insurance Bill', title: 'The National Insurance Act', date: '1946',
      text: 'The Act that carried out most of the Beveridge plan: flat-rate contributions from every adult worker in return for sickness and unemployment benefit, widows\' benefits, maternity grants and old-age pensions. It came into force with the health service on 5 July 1948.' },
    { id: 'mcmahon', m: 'atomic secrets', title: 'The McMahon Act and the British bomb', date: '1946–47',
      text: 'British scientists had worked on the American atomic project, but the US Atomic Energy Act of August 1946 cut Britain off from its results. In January 1947 a small secret committee of ministers decided that Britain would build its own bomb. Parliament was not told until May 1948, and the first British test came in October 1952.' },
    { id: 'national-labour', m: 'National Labour', title: 'National Labour', date: '1931–45',
      text: 'The small group who followed the Labour Prime Minister into the National Government in 1931 and were expelled from the Labour Party. It held a handful of seats with Conservative support and was wound up in 1945.' },
    { id: 'dock-strike-1949', m: 'Canadian seamen|two Canadian ships', title: 'The dock strike of 1949', date: 'June–July 1949',
      text: 'London dockers refused to unload two Canadian ships caught up in a dispute between rival seamen\'s unions, and were locked out. The Labour government declared a state of emergency and sent troops to move food. It believed the strike was organised by Communists.' },
    { id: 'devaluation', m: 'devalue', title: 'Devaluation', date: '18 September 1949',
      text: 'With the dollar reserves draining again, the pound was devalued from $4.03 to $2.80, a cut of about thirty per cent. The Chancellor had denied any such plan many times beforehand.' },
    { id: 'korea', m: 'In Korea', title: 'The Korean War', date: '1950–53',
      text: 'North Korea invaded the South in June 1950. The United Nations sent forces under American command, Britain among them. When Chinese armies entered the war in November 1950, President Truman said the use of atomic weapons had always been under consideration, and the British Prime Minister flew to Washington to seek reassurance.' },
    { id: 'election-1951', m: 'go to the country', title: 'The 1951 election', date: '25 October 1951',
      text: 'Labour won more votes than in 1945, and more than the Conservatives, but fewer seats: 295 to 321. It would be thirteen years before Labour governed again.' },
    { id: 'partner-debts', m: 'the clients\' money has gone with him', title: 'A partner\'s debts', date: '1890s',
      text: 'Before limited liability became usual for professional firms, every partner was personally liable for the firm\'s debts, including money a dishonest partner had taken. The 1890s saw a run of such ruins, the worst being the collapse of the Liberator Building Society in 1892, which swallowed the savings of thousands of small investors.' },
    { id: 'yorkshire-college', m: 'Yorkshire College', title: 'The Yorkshire College', date: '1874–1904',
      text: 'A college of science founded in Leeds in 1874, which taught evening classes to working men and women alongside day students. It became the University of Leeds in 1904.' },
    { id: 'anthracite', m: 'anthracite', title: 'The anthracite coalfield', date: '',
      text: 'The western end of the South Wales coalfield, around Ammanford and the Amman and Gwendraeth valleys, mined anthracite, a hard, clean-burning coal prized for ships and stoves. Its villages were Welsh-speaking and chapel-going, and its pits small and often family-owned.' },
    { id: 'school-board', m: 'School Board', title: 'The School Boards', date: '1870–1902',
      text: 'Elected boards set up under the Education Act of 1870 to build and run elementary "board schools" where church schools were not enough. Women could vote for them and sit on them. The Education Act of 1902 abolished them and handed schools to county and borough councils.' },
    { id: 'pupil-teacher', m: 'pupil-teacher', title: 'Pupil-teachers', date: '1846–c.1910',
      text: 'Bright working-class boys and girls of thirteen or fourteen apprenticed to a school, teaching classes by day and studying by night, in the hope of winning a place at a training college. Most elementary teachers of the period began this way.' },
    { id: 'poor-scholars', m: 'Christ\'s College, Cambridge', title: 'Poor scholars at Cambridge', date: 'before 1914',
      text: 'Oxford and Cambridge were overwhelmingly the preserve of the public schools. A handful of county and college scholarships went to boys from elementary schools, but they often covered fees and not living costs, and many scholarship boys left without degrees.' },
    { id: 'divi', m: 'the divi', title: 'The Co-op and the divi', date: 'from 1844',
      text: 'Following the Rochdale Pioneers of 1844, co-operative societies sold groceries and goods to members and returned the profits as a dividend on what each had spent. By 1914 the movement had three million members, its own wholesale society, banks, factories and schools.' },
    { id: 'nut', m: 'National Union of Teachers', title: 'The National Union of Teachers', date: 'from 1870',
      text: 'The union of elementary school teachers, founded in 1870. It fought for pay scales, pensions and security of tenure, and for married women teachers\' right to keep their posts.' },
    { id: 'wea', m: 'Workers\' Educational Association', title: 'The Workers\' Educational Association', date: 'from 1903',
      text: 'A movement founded in 1903 to bring university teaching to working people. Its tutorial classes ran for three winters, meeting weekly, with written work and university tutors. Many Labour MPs and union leaders of the next generation studied in them.' },
    { id: 'reserved', m: 'Miners are needed in the pits', title: 'Reserved occupations', date: '1914–18',
      text: 'Coal was the fuel of the Navy and of industry, and mining became a reserved occupation from which men were not conscripted. Even so, about a quarter of a million miners volunteered in the first year of the war.' },
    { id: 'somme', m: 'The battalion goes over at dawn', title: 'The Somme', date: 'July–November 1916',
      text: 'The great British and French offensive on the Somme opened on 1 July 1916 with almost 20,000 British dead on the first day. It went on for four and a half months. Most of the volunteer Kitchener battalions fought there; British casualties were over 400,000.' },
    { id: 'comb-out', m: 'comb-out', title: 'The comb-outs', date: '1917–18',
      text: 'As the army ran short of men, exemptions from conscription were withdrawn in batches from younger workers in reserved trades, including mining. The comb-outs caused bitter disputes in the coalfields, where the Miners\' Federation had been promised its men would be spared.' },
    { id: 'fisher-act', m: 'new Education Act', title: 'The Education Act of 1918', date: '1918',
      text: 'The Act raised the school-leaving age to fourteen everywhere and promised part-time continuation schools for young workers up to sixteen. In the spending cuts of 1921–22 nearly all of the continuation schools were abandoned.' },
    { id: 'labour-college', m: 'Central Labour College', title: 'The Central Labour College', date: '1909–29',
      text: 'A residential college in London founded by students who walked out of Ruskin College, Oxford, in 1909. It was paid for by the South Wales miners and the railwaymen and taught Marxist economics and history. Many union leaders and Labour MPs studied there.' },
    { id: 'coop-party', m: 'a party of its own', title: 'The Co-operative Party', date: 'from 1917',
      text: 'Angered by wartime taxes and rationing that favoured private traders, the co-operative movement formed its own political party in 1917. Its first MP was elected in 1918. From 1927 it stood candidates jointly with Labour, as it still does.' },
    { id: 'research-dept', m: 'research department now', title: 'Labour\'s research department', date: 'from 1920',
      text: 'Labour set up a joint research and information department with the TUC after the war, to supply facts and policy to a party that expected to govern. It was small, poor and overworked, and its papers were often ignored by the leadership.' },
    { id: 'agent', m: 'full-time agent', title: 'The party agent', date: '',
      text: 'The paid organiser of a constituency party, who kept the register, ran the canvass and managed the candidate\'s expenses within the strict limits of the law. A good agent was worth thousands of votes, and many agents later became Members themselves.' },
    { id: 'labour-nation', m: 'a programme for the next election', title: 'Labour and the Nation', date: '1928',
      text: 'Labour\'s programme for the 1929 election: some seventy proposals for nationalisation, housing, pensions and peace, set out without priorities or timetable. It helped win the election, but gave the government no plan when the slump came.' },
    { id: 'scurr', m: 'school-leaving age to fifteen', title: 'The school-leaving age', date: '1929–31',
      text: 'The second Labour government tried to raise the school-leaving age from fourteen to fifteen. Roman Catholic and Anglican schools said they could not pay for the extra places, and in January 1931 Catholic Labour MPs helped carry an amendment that wrecked the Bill. The age was raised only in 1947.' },
    { id: 'company-union', m: 'company union', title: 'The company union', date: '1926–38',
      text: 'After the 1926 lockout some South Wales coal owners recognised only the South Wales Miners\' Industrial Union, a "non-political" union friendly to management, and victimised Federation men. Stay-down strikes and ballots in 1935–37 broke it, and it merged back in 1938.' },
    { id: 'ldv', m: 'Local Defence Volunteers', title: 'The Home Guard', date: 'from 14 May 1940',
      text: 'Called for in a radio broadcast on 14 May 1940 to watch for German parachutists. About a quarter of a million men volunteered within a day, and over a million by the summer. Renamed the Home Guard in July 1940, it was armed at first with shotguns, pikes and broom handles.' },
    { id: 'air-gap', m: 'Coastal Command', title: 'The Atlantic air gap', date: '1941–43',
      text: 'In mid-Atlantic, beyond the range of shore-based aircraft, U-boat packs could attack convoys unseen. Coastal Command begged for long-range bombers; Bomber Command wanted them for Germany. The gap was closed only in spring 1943, and the U-boats were beaten soon after.' },
    { id: 'first-lord', m: 'First Lord of the Admiralty', title: 'First Lord of the Admiralty', date: '',
      text: 'The Cabinet minister responsible for the Royal Navy. The professional head was the First Sea Lord. In both world wars the post was held by men who went on to be Prime Minister, and in the second the Prime Minister went on running the Navy after he left it.' },
    { id: 'education-1944', m: 'free secondary schooling', title: 'The Education Act 1944', date: 'August 1944',
      text: 'The coalition\'s Act made secondary education free for all, divided into grammar, technical and modern schools by an examination at eleven, raised the leaving age to fifteen from 1947, and settled the church schools\' finances. It shaped English schooling for a generation.' },
    { id: 'equal-pay', m: 'equal pay', title: 'Equal pay for women teachers', date: 'March 1944',
      text: 'On 28 March 1944 the Commons voted 117 to 116 for an amendment giving women teachers the same pay as men. The Prime Minister made reversing it a matter of confidence, and it was struck out two days later. Equal pay for teachers came in stages from 1955.' },
    { id: 'national-service', m: 'National Service Bill', title: 'National Service', date: '1947–60',
      text: 'Peacetime conscription: every young man served in the forces at eighteen. After a Labour revolt the term was cut from eighteen months to twelve, then raised to eighteen in 1948 and to two years during the Korean War. The last national servicemen left in 1963.' },
    { id: 'mercy', m: 'Only you can stop it', title: 'The prerogative of mercy', date: '',
      text: 'Every death sentence in England went to the Home Secretary, who advised the King whether to commute it to life imprisonment. About half were reprieved. The decision was the Home Secretary\'s alone, made on the file, usually within days of the execution date.' },
    { id: 'golden-jubilee', m: 'Fifty years of the Queen', title: 'The Golden Jubilee', date: 'June 1887',
      text: 'Queen Victoria\'s fifty years on the throne were celebrated on 20 and 21 June 1887 with a service at Westminster Abbey, a banquet for fifty kings and princes, and teas, bonfires and sports in almost every parish, usually paid for by the local gentry.' },
    { id: 'relieving-officer', m: 'relieving officer', title: 'The relieving officer', date: '1834–1930',
      text: 'The official of the Poor Law union who decided who got help. Help mostly meant the workhouse, where families were split up and children went to the workhouse school. A pauper burial, paid for by the parish, was a lasting shame for working families.' },
    { id: 'school-pence', m: 'school pence', title: 'The school pence', date: 'to 1891',
      text: 'Until 1891 most parents paid a few pence a week for each child at an elementary school, and poor families often kept children at home to save it. The Elementary Education Act of 1891 paid schools a grant instead, making elementary schooling effectively free.' },
    { id: 'labourers-union', m: 'agricultural labourers\' union', title: 'The farm labourers\' unions', date: '1872–96',
      text: 'Joseph Arch\'s National Agricultural Labourers\' Union, founded in 1872, briefly organised tens of thousands of farm workers before the farmers broke it with lockouts. It revived around 1890 and collapsed again. Farm wages in the south-west were among the lowest in England, about eleven shillings a week.' },
    { id: 'pit-age', m: 'the pits take boys at twelve', title: 'Boys in the pits', date: '1887',
      text: 'The Coal Mines Regulation Act of 1887 set the minimum age for boys working underground at twelve. Most began as trappers, opening and shutting ventilation doors in the dark for ten hours a day.' },
    { id: 'trapper', m: 'trapper', title: 'The trapper', date: '',
      text: 'The youngest job underground: a boy sat alone by a ventilation door and opened it for the tubs and ponies, then shut it so that the air kept flowing to the coalface. If he fell asleep, gas could build up. Many trappers worked without a light.' },
    { id: 'horse-trams', m: 'horse trams', title: 'Bristol\'s trams', date: '1875–1900',
      text: 'Bristol\'s horse trams were run by a private company famous for long hours, low pay and fierce hostility to unions. The lines were electrified from 1895. Conductors worked up to fifteen hours a day and were fined for short fares and lost tickets.' },
    { id: 'baptists', m: 'Baptist chapel', title: 'Chapel', date: '',
      text: 'Nonconformist chapels, Baptist, Methodist and Congregational, were the great schools of working-class speakers. Lay preachers learned to hold a crowd without notes, and many early union leaders and Labour MPs began in the pulpit.' },
    { id: 'bristol-socialists', m: 'Bristol Socialist Society', title: 'The Bristol Socialist Society', date: 'from 1885',
      text: 'One of the oldest socialist groups in the country, founded in 1885. It held open-air meetings, ran a choir and a Sunday school, and helped organise the gasworkers and dockers of Bristol in the 1890s.' },
    { id: 'right-to-work', m: 'Right to Work committee', title: 'The Right to Work campaign', date: '1905–09',
      text: 'A national campaign for a law obliging councils to provide work for the unemployed. Local committees organised marches, deputations and protests during the slumps of 1905 and 1908. Labour\'s Right to Work Bill of 1907–08 was defeated.' },
    { id: 'dockers-union', m: 'dock union', title: 'The Dockers\' Union', date: 'from 1889',
      text: 'The Dock, Wharf, Riverside and General Labourers\' Union, born of the 1889 strike, organised dock labourers in London, Bristol, South Wales and elsewhere. Casual hiring at the dock gate, where men were picked by the foreman each morning, was its great grievance.' },
    { id: 'great-unrest', m: 'whole transport trade is out', title: 'The Great Unrest', date: '1910–14',
      text: 'A wave of huge strikes by seamen, dockers, railwaymen and miners as prices rose faster than wages. In the summer of 1911 troops were sent into many towns; soldiers shot dead two men in Liverpool and two in Llanelli.' },
    { id: 'dilution', m: 'dilution', title: 'Dilution', date: '1915–18',
      text: 'Letting unskilled men, and women, do work previously reserved for skilled tradesmen, so that war production could rise. The unions accepted it on condition that the old rules came back after the war.' },
    { id: 'ruskin', m: 'Ruskin College', title: 'Ruskin College', date: 'from 1899',
      text: 'A college in Oxford for working men, founded in 1899 by two Americans and named after John Ruskin. It was not part of the university. Unions and lodges paid for members to spend a year or two there.' },
    { id: 'rfa', m: 'Royal Field Artillery', title: 'The Royal Field Artillery', date: '',
      text: 'The arm that worked the field guns. Its drivers brought ammunition and guns forward by night with six-horse teams, along roads the enemy had registered for shelling. Miners and carters who knew horses were prized.' },
    { id: 'half-time', m: 'half-timer', title: 'The half-time system', date: 'to 1918',
      text: 'In the Lancashire cotton towns children from the age of ten, later twelve, worked half the day in the mill and spent the other half at school. Teachers said half-timers fell asleep at their desks. The Education Act of 1918 ended the system.' },
    { id: 'price-list', m: 'price list', title: 'The price list', date: '',
      text: 'Weavers and miners were paid by the piece, at rates set out in long, detailed lists agreed between unions and employers. Cutting the list was the usual way to cut wages, and most big disputes began there.' },
    { id: 'cotton-boom', m: 'cotton trade is booming', title: 'The cotton boom', date: '1919–20',
      text: 'After the war Lancashire mills were bought and refloated at several times their value, with borrowed money, in expectation of endless demand. The boom collapsed in 1920–21, leaving the industry crippled by debt as Japanese and Indian mills took its markets.' },
    { id: 'natsopa', m: 'operative printers\' assistants', title: 'NATSOPA', date: 'from 1889',
      text: 'The National Society of Operative Printers\' Assistants, the union of the machine-room men, paper-handlers and other non-craft workers in printing. The old craft unions of compositors looked down on it.' },
    { id: 'press-barons', m: 'press barons', title: 'The press barons', date: 'from 1896',
      text: 'Newspaper proprietors who bought up dozens of papers and built cheap mass-circulation dailies, beginning with the Daily Mail in 1896. Their papers needed huge machine rooms working all night, and they fought the print unions hard.' },
    { id: 'shaw-inquiry', m: 'court of inquiry', title: 'The Shaw Inquiry', date: 'February–March 1920',
      text: 'A court of inquiry set up under the Industrial Courts Act 1919 to decide dockers\' pay. The union\'s case was argued by its own organiser against the employers\' counsel. It awarded a national minimum of sixteen shillings a day and called for an end to casual hiring.' },
    { id: 'council-action', m: 'Council of Action', title: 'The Council of Action', date: 'August 1920',
      text: 'A joint body of the Labour Party and the TUC formed to stop Britain going to war against Soviet Russia on Poland\'s side. It threatened a general strike, and local councils of action sprang up across the country. Britain did not intervene.' },
    { id: 'polish-soviet', m: 'Poland has invaded Soviet Russia', title: 'The Polish–Soviet War', date: '1919–21',
      text: 'Poland, newly independent, fought Soviet Russia over the borderlands. A Polish offensive took Kiev in May 1920; the Red Army drove the Poles back to the gates of Warsaw, where it was beaten in August.' },
    { id: 'tgwu', m: 'Transport and General Workers\' Union', title: 'The TGWU', date: 'from 1922',
      text: 'Formed on 1 January 1922 from fourteen unions of dockers, carters, busmen, tramwaymen and others, with about 300,000 members, it was soon the largest union in the world. Its general secretary was one of the most powerful men in the Labour movement.' },
    { id: 'first-labour', m: 'Labour is in office at last', title: 'The first Labour government', date: 'January–November 1924',
      text: 'Labour took office in January 1924 as a minority government depending on Liberal votes. It lasted nine months. Its ministers were anxious to prove themselves fit to govern, and were embarrassed when unions struck against employers while they were in office.' },
    { id: 'gold-standard', m: 'gold standard', title: 'The gold standard', date: '1925–31',
      text: 'Britain went back to gold at the pre-war rate in 1925, which made exports dear and pushed employers to cut wages. Bankers treated it as a matter of national honour. The financial crisis of September 1931 forced Britain off it, and the sky did not fall.' },
    { id: 'herald', m: 'Daily Herald', title: 'The Daily Herald', date: '1912–64',
      text: 'The Labour movement\'s daily paper, owned from 1922 by the TUC and the Labour Party. Relaunched in 1930 in partnership with a commercial publisher, it became for a time the best-selling daily in the world.' },
    { id: 'may-report', m: 'cuts unemployment benefit by ten per cent|cut unemployment benefit by ten per cent', title: 'The crisis of August 1931', date: 'August 1931',
      text: 'A government committee forecast a huge budget deficit, and foreign bankers would lend only if spending was cut, including unemployment benefit. The Labour Cabinet split over a ten per cent cut. The Prime Minister formed a National Government with the Conservatives and Liberals, and was expelled from Labour.' },
    { id: 'irsf', m: 'tax clerks\' union', title: 'White-collar unions', date: '',
      text: 'Civil service clerks had their own unions, cautious and respectable, barred until 1946 from affiliating to the TUC by the Trade Disputes Act of 1927. Several Labour ministers of the 1940s and after began as their officials.' },
    { id: 'coronation', m: 'eve of the Coronation', title: 'The Coronation of 1937', date: '12 May 1937',
      text: 'George VI was crowned on 12 May 1937, the date fixed for his brother before the abdication. Hotels, theatres and transport in London expected record crowds, which gave London\'s busmen leverage they had never had before.' },
    { id: 'non-intervention', m: 'Spain is burning|proposed non-intervention', title: 'Non-intervention in Spain', date: '1936–39',
      text: 'Britain and France sponsored an agreement by which the powers would supply arms to neither side in the Spanish Civil War. Germany and Italy broke it openly. The Labour movement first accepted it, then turned against it as a policy that starved the Republic.' },
    { id: 'jarrow', m: 'Two hundred men from Jarrow', title: 'Jarrow', date: '1936',
      text: 'A shipbuilding town on the Tyne whose yard was closed in 1934 by a shipowners\' scheme to cut capacity. Unemployment reached about seventy per cent. In October 1936 two hundred of its men marched to London with a petition; the Prime Minister would not see them.' },
    { id: 'more-looms', m: 'eight looms instead of four', title: 'More looms', date: '1929–32',
      text: 'Lancashire masters tried to compete with cheap Japanese and Indian cloth by having each weaver mind more looms, six or eight instead of four, at lower rates. It meant fewer weavers. Strikes and lockouts spread across the county until a settlement in 1932.' },
    { id: 'conchie-label', m: 'conscientious objector of the last war', title: 'The objectors, afterwards', date: 'after 1918',
      text: 'About sixteen thousand men claimed conscientious objection in the First World War. Those who had refused all service lost the vote for five years under the 1918 Act, and many found that employers and neighbours never forgave them.' },
    { id: 'tariff-1923', m: 'snap election on tariffs', title: 'The 1923 election', date: 'December 1923',
      text: 'The new Conservative Prime Minister called an election only a year after the last, to seek a mandate for tariffs. He lost his majority. Labour, with 191 seats, formed its first government with Liberal tolerance in January 1924.' },
    { id: 'ewo', m: 'Essential Work Order', title: 'The Essential Work Order', date: 'March 1941',
      text: 'An order under the wartime emergency powers that tied workers in essential industries to their jobs: they could not leave, or be sacked, without a Ministry of Labour officer\'s consent. In return employers had to pay a guaranteed weekly wage and meet standards of welfare.' },
    { id: 'bevin-boys', m: 'sent down the mines instead of to the forces', title: 'The Bevin Boys', date: '1943–48',
      text: 'One in ten young men called up, chosen by drawing a digit from a hat, was sent to the coal mines instead of the forces. About 48,000 served. Many were mocked as dodgers; they received no campaign medals and were officially recognised only in 2008.' },
    { id: 'reg-1aa', m: 'five years in prison for anyone who incites a strike|Regulation 1AA', title: 'Regulation 1AA', date: 'April 1944',
      text: 'A wartime regulation making it a crime, punishable by five years\' imprisonment, to instigate or incite a strike in an essential service. It was aimed at Trotskyist agitators in the pits and shipyards, and was attacked by the Labour left as an assault on the right to strike.' },
    { id: 'potsdam', m: 'Potsdam', title: 'The Potsdam Conference', date: '17 July – 2 August 1945',
      text: 'The last conference of the wartime Big Three, held at Potsdam outside Berlin to settle the occupation of Germany and the borders of Poland. Britain\'s delegation changed halfway through, when the election results brought a new Prime Minister and Foreign Secretary.' },
    { id: 'palestine-mandate', m: 'Palestine is ungovernable', title: 'The Palestine Mandate', date: '1920–48',
      text: 'Britain governed Palestine under a League of Nations mandate, promising a national home for the Jewish people while protecting the Arab majority. After the war, with Jewish survivors of the Holocaust seeking entry and Jewish and Arab armed groups in conflict, Britain limited immigration, referred the question to the United Nations in 1947 and withdrew in May 1948.' },
    { id: 'king-david', m: 'King David Hotel', title: 'The King David Hotel bombing', date: '22 July 1946',
      text: 'The Irgun, a Jewish underground group, bombed the wing of the King David Hotel in Jerusalem that housed the British administration, killing 91 people, British, Arab and Jewish. In July 1947 the Irgun also hanged two captured British sergeants.' },
    { id: 'marshall', m: 'help pay for it', title: 'The Marshall Plan', date: '1948–52',
      text: 'The European Recovery Program, offered by Secretary of State George Marshall in June 1947. America gave Western Europe about thirteen billion dollars for food, fuel and machinery. Britain received the largest share. The Soviet Union refused it and forbade Eastern Europe to take part.' },
    { id: 'plot-1947', m: 'the winter crisis has shaken everyone', title: 'The 1947 plot', date: 'September 1947',
      text: 'After the fuel crisis and the convertibility crisis, a senior minister proposed to the Prime Minister that he stand down in favour of the Foreign Secretary. The Foreign Secretary refused, and the Prime Minister promoted the plotter instead.' },
    { id: 'berlin-airlift', m: 'blockaded Berlin', title: 'The Berlin airlift', date: 'June 1948 – May 1949',
      text: 'When the Soviet Union cut road and rail links to West Berlin, American and British aircraft flew in food and coal for two million people, at times landing every few minutes. The blockade was lifted in May 1949.' },
    { id: 'lord-privy-seal', m: 'Lord Privy Seal', title: 'Lord Privy Seal', date: '',
      text: 'One of the ancient offices of state, with no department and no real duties. It was used to give a seat in Cabinet to a minister doing a special job, or to an elder statesman being eased out.' },
    { id: 'blitz-death', m: 'killed in an air raid', title: 'Civilian deaths', date: '1940–45',
      text: 'About 60,000 civilians were killed by bombing in Britain during the war, half of them in London. Families learned of deaths by telegram or from the police, and many were buried from the house in a private funeral.' },
    { id: 'demob', m: 'Five million men want to come home', title: 'Demobilisation', date: '1945–47',
      text: 'Men were released from the forces in order of age and length of service, a scheme designed to avoid the chaos and mutinies of 1919. It was fair and slow. In early 1946 airmen and soldiers in India and the Middle East protested at the pace.' },
    { id: 'windrush', m: 'Empire Windrush', title: 'The Empire Windrush', date: 'June 1948',
      text: 'A troopship that arrived at Tilbury on 21–22 June 1948 carrying about five hundred passengers from the Caribbean, many of them ex-servicemen. As British subjects they had the right to settle. Most found work within weeks; their arrival came to symbolise the beginning of post-war Commonwealth immigration.' },
    { id: 'horsa', m: 'school-leaving age is due to rise', title: 'Raising the school-leaving age', date: '1 April 1947',
      text: 'The 1944 Act raised the leaving age to fifteen from April 1947. With no materials for new schools, the government put up prefabricated classrooms (the HORSA huts) and trained thousands of ex-servicemen as teachers in one-year emergency courses.' },
    { id: 'brs', m: 'British Road Services', title: 'Nationalised transport', date: '1948',
      text: 'The Transport Act 1947 brought the railways, canals, London Transport and long-distance road haulage under a British Transport Commission. British Road Services ran the nationalised lorries. Many workers found the managers unchanged.' },
    /* ── The Firebrand, Act I ── */
    { id: 'welsh-revival', m: 'collier-preacher from Loughor', title: 'The Welsh Revival', date: '1904–05',
      text: 'A religious revival that swept the Welsh valleys in the winter of 1904–05, led by Evan Roberts, a young former collier training for the ministry. Chapels held meetings every night, drinking and swearing fell away for a time, and tens of thousands joined the chapels. Many later socialists grew up in its afterglow; others, like many colliers, turned from it to politics.' },
    { id: 'old-age-pensions', m: 'first old-age pensions', title: 'Old-age pensions', date: '1909',
      text: 'The Liberal government\'s Old Age Pensions Act of 1908 paid up to five shillings a week to people over seventy with small incomes, at the post office and without contributions. People who had been on poor relief, or judged to have failed to work, were shut out at first. For many it was the first money they had ever had from the state without shame.' },
    { id: 'tredegar-riot', m: 'breaking the windows of the Jewish shops', title: 'The Tredegar riot', date: 'August 1911',
      text: 'In the hot, strike-ridden August of 1911, crowds in Tredegar and other Monmouthshire valley towns attacked and looted Jewish-owned shops over several nights, and troops were sent in. Chapel ministers and labour leaders condemned it; historians still argue over how far it was about rents and debt and how far plain antisemitism.' },
    { id: 'county-scholarship', m: 'sit for a scholarship to a county school', title: 'The scholarship ladder', date: 'from 1902',
      text: 'After the 1902 Education Act a few elementary-school children won free places or scholarships to county secondary schools. For a working-class family it meant years without the child\'s wages, so many who passed never went. Most children left school at twelve or thirteen for work.' },
    { id: 'workmens-library', m: "Workmen's Library", title: 'The workmen\'s libraries', date: '',
      text: 'The miners\' institutes of South Wales, paid for by a penny or so a week from each collier\'s wages, ran some of the best working-class libraries in Britain, stocked with history, economics, novels and socialist classics. Tredegar\'s was one of the finest, and a generation of miners\' leaders educated themselves in them.' },
    { id: 'black-friday', m: 'on Friday they called it off', title: 'Black Friday', date: '15 April 1921',
      text: 'The miners, railwaymen and transport workers had formed a Triple Alliance to strike together. When the government handed the mines back to the owners in 1921 and wages were cut, the miners were locked out; on Friday 15 April the other two unions called off their sympathy strike. The miners fought on alone and were beaten by June. The day became a byword for betrayal.' },
    { id: 'intervention', m: 'intervene against the Bolsheviks', title: 'Intervention in Russia', date: '1918–20',
      text: 'British, French, American and Japanese troops landed in Russia in 1918, first to keep supplies from the Germans and then to help the White armies against the Bolsheviks. The labour movement campaigned against it under the slogan "Hands off Russia", and the last British troops left in 1920.' },
    { id: 'seafarers', m: 'broken away from their old national union', title: 'The seamen\'s breakaway', date: '1911–12',
      text: 'After the great seamen\'s strike of 1911, Glasgow seamen who thought the national union too close to the shipowners formed the British Seafarers\' Union in 1912. It was a fighting local union, small and poor, and later merged into what became the National Union of Seamen.' },
    { id: 'rent-strikes', m: 'rent strike', title: 'The Glasgow rent strikes', date: '1915',
      text: 'When war workers flooded into Glasgow and landlords raised rents, tenants, led by working-class women such as Mary Barbour, refused to pay and drove off the bailiffs. When the shipyard workers threatened to strike in support, the government rushed through a law freezing rents at their pre-war level in December 1915.' },
    { id: 'forty-hours', m: 'forty-hour week', title: 'The forty-hours strike', date: 'January 1919',
      text: 'Clydeside workers struck in January 1919 for a forty-hour week to make room for demobilised soldiers. On 31 January police charged a mass rally in George Square. The government, fearing revolution, sent in troops and tanks, and the strike leaders were arrested. "Red Clydeside" became a legend on the left and a fear on the right.' },
    { id: 'finnish-civil-war', m: 'civil war in which the Whites', title: 'The Finnish civil war', date: '1918',
      text: 'Finland broke away from Russia in December 1917, and in 1918 fought a short, savage civil war between socialist Reds and conservative Whites, who won with German help. Thousands of Reds were executed after the fighting, and many more died in prison camps.' },
    /* ── The Firebrand, Act II ── */
    { id: 'dole-household', m: 'stopped your dole because your sister earns', title: 'The dole and the household', date: '1920s',
      text: 'Unemployment benefit, "the dole", was paid for a limited number of weeks, and after that relief could be cut or stopped if anyone else in the household was earning. A son or daughter\'s wages were counted against the father, or a brother\'s against a sister, which broke up families as young earners moved out so that their parents could claim.' },
    { id: 'pneumoconiosis', m: 'not an industrial disease', title: 'Dust disease', date: '',
      text: 'Pneumoconiosis, the scarring of the lungs by coal dust, killed and crippled miners by the thousand. Compensation law recognised silicosis from rock dust first, from 1928, but coal-dust disease was not fully brought into the compensation schemes until the 1940s. Many miners died breathless at home with nothing paid.' },
    { id: 'guardians-default', m: 'used his new Act', title: 'The Guardians suspended', date: '1926–27',
      text: 'Elected Boards of Guardians ran the Poor Law locally. When Labour boards in West Ham, Chester-le-Street and Bedwellty paid generous relief to strikers\' and locked-out miners\' families and borrowed to do it, the Minister of Health took power under the Board of Guardians (Default) Act 1926 to replace them with appointed commissioners, who cut relief back.' },
    { id: 'medical-aid-society', m: 'Tredegar Medical Aid Society', title: 'The Tredegar Medical Aid Society', date: 'from 1890',
      text: 'A scheme run by the workers of Tredegar in which a few pence a week from every pay packet bought doctors, dentists, medicines, and later a hospital and X-rays for the whole family. By the 1920s it covered almost the entire town. It was one of several such schemes in the valleys, and the model Bevan said the NHS followed.' },
    { id: 'the-fed', m: 'an old Federation man', title: 'The Fed', date: 'founded 1898',
      text: 'The South Wales Miners\' Federation, "the Fed", organised the miners of the valleys through its local lodges. Its lodges chose councillors, magistrates and Members of Parliament, ran libraries, halls and hospitals, and made the coalfield one of the most solidly Labour places on earth.' },
    { id: 'lockout-1926-gloss', m: 'miners are locked out again|the miners are still locked out', title: 'The 1926 lockout', date: 'May–December 1926',
      text: 'The coal owners demanded longer hours and lower pay in 1926. The TUC called a General Strike in the miners\' support for nine days in May, then called it off; the miners stayed out alone for seven months, living on relief, soup kitchens and coal picked from the tips, and went back beaten in the winter on the owners\' terms.' },
    { id: 'red-clydeside', m: 'Clydesiders', title: 'The Clydesiders', date: '1922',
      text: 'At the 1922 election Labour, mostly ILP men, won ten of Glasgow\'s fifteen seats. The new Members, led by James Maxton, John Wheatley and David Kirkwood, went to Westminster promising to end the slums and became famous for their fiery speeches and their rows with the Speaker and their own leaders.' },
    { id: 'mines-department', m: 'Secretary for Mines', title: 'The Mines Department', date: '1920–42',
      text: 'A sub-department of the Board of Trade set up in 1920 to oversee the coal industry, headed by a Secretary for Mines who was a junior minister, outside the Cabinet. It dealt with safety, wages and the endless crises of the industry, but had no power to run the pits, which stayed with the private owners until 1947.' },
    { id: 'workmens-comp', m: 'crushed foot', title: 'Workmen\'s compensation', date: 'from 1897',
      text: 'Injured workers could claim compensation from their employers under the Workmen\'s Compensation Acts, but employers and their insurers fought claims hard, arguing drunkenness, carelessness or that the injury came from something else. A good solicitor could make the difference between a pension and the workhouse.' },
    { id: 'little-moscow', m: 'Little Moscow', title: 'Little Moscow', date: '',
      text: 'Nelson, a weaving town in north-east Lancashire, was known for its radical politics: a strong Labour council, socialist clubs and Sunday schools, a Clarion cycling club and mass meetings. The nickname "Little Moscow" was meant as an insult by its opponents and worn with pride by many in the town.' },
    { id: 'kristallnacht', m: 'synagogues of Germany have burned', title: 'Kristallnacht', date: '9–10 November 1938',
      text: 'A nationwide pogrom against Jews in Germany and Austria, organised by the Nazi party: synagogues burned, shops and homes wrecked, about ninety people killed and some thirty thousand Jewish men sent to concentration camps. Britain responded by admitting about ten thousand unaccompanied children on the Kindertransport, and adults who had a guarantor.' },
    { id: 'mosley-memo', m: 'his plan for public works and protection', title: 'The Moseby memorandum', date: '1930',
      text: 'A plan put to the Labour Cabinet in 1930 by one of its junior ministers: public works, cheap credit, protection of home industry and planning to beat unemployment. The Cabinet rejected it; its author resigned and published it as a manifesto, then left Labour in 1931 to found the New Party, which drifted within a year into fascism.' },
    { id: 'blackshirts', m: 'Blackshirts', title: 'The Blackshirts', date: '1932–40',
      text: 'The British Union of Fascists, founded in 1932, marched in black uniforms and staged rallies with stewards who beat up hecklers. In the East End it turned to open antisemitism. After Cable Street the Public Order Act 1936 banned political uniforms, and in 1940 its leaders were interned.' },
    { id: 'transport-house', m: 'Transport House', title: 'Transport House', date: '',
      text: 'The headquarters of the Transport and General Workers\' Union in Smith Square, Westminster, which also housed the Labour Party and the TUC from 1928. "Transport House" came to mean the party machine: the national agent, the executive and the officials who drew up lists of approved candidates.' },
    { id: 'open-air', m: 'a street corner, a chapel vestry', title: 'The open-air meeting', date: '',
      text: 'Before radio and television reached most homes, politics was spoken aloud: on soapboxes at street corners and pit gates, in chapel vestries, co-operative halls and market squares, night after night. Left-wing speakers learned their craft against hecklers, rain and the police, and judged themselves by whether the crowd stayed.' },
    /* ── The Firebrand, Act III ── */
    { id: 'map', m: 'Minister of Aircraft Production', title: 'The Ministry of Aircraft Production', date: '1940–46',
      text: 'Created in May 1940 to speed up the building of fighters and bombers. Its first minister, the press lord Beaverbrook, cut through red tape, raided other departments for materials and men, and appealed to the public for aluminium pots and pans. Fighter output rose sharply through the summer of the Battle of Britain.' },
    { id: 'riegner', m: 'World Jewish Congress', title: 'The Riegner telegram', date: 'August 1942',
      text: 'In August 1942 Gerhart Riegner, the World Jewish Congress representative in Geneva, sent word through the British and American governments that the Nazis planned to murder all the Jews of occupied Europe. Officials doubted it and delayed. In December 1942 the Allies publicly confirmed and condemned the extermination, but rescue remained very limited.' },
    { id: 'electoral-truce', m: 'electoral truce', title: 'The electoral truce', date: '1939–45',
      text: 'During the war the three main parties agreed not to fight each other at by-elections: when a seat fell vacant, the party that held it put up a candidate unopposed by the others. Independents and small parties such as Common Wealth fought anyway, and won several seats from 1942 as the country moved left.' },
    { id: 'health-plans', m: 'left half-drafted', title: 'Plans for a health service', date: '1942–45',
      text: 'The Beveridge Report of 1942 assumed a national health service, and the coalition published a White Paper in 1944 promising one, free to all. But it left the hospitals with their owners and the doctors largely as they were, and the BMA fought even that. The incoming Labour government had to decide what the service would actually be.' },
    { id: 'voluntary-hospitals', m: 'rattling tins in the street', title: 'The voluntary hospitals', date: 'before 1948',
      text: 'Before the NHS, Britain\'s hospitals were a patchwork. The great voluntary hospitals were charities, run by boards of governors and funded by gifts, flag days, workers\' contribution schemes and fees; many were near bankrupt by the 1940s. The councils ran the municipal hospitals, many of them old workhouse infirmaries.' },
    { id: 'squatters', m: 'empty army camps', title: 'The squatters', date: '1946',
      text: 'In the summer of 1946, with millions short of a home, some 40,000 people moved into empty army and air force camps across Britain, and the government, in the main, let them stay. In September, Communist-led squatters occupied empty flats and a hotel in central London; the occupations ended after legal action.' },
    { id: 'bma', m: 'plebiscite', title: 'The doctors\' revolt', date: '1946–48',
      text: 'The British Medical Association fought the NHS for two years, fearing that doctors would become salaried state employees and lose their freedom and their private patients. Its members voted overwhelmingly against the terms in early 1948. Concessions, above all to the hospital consultants, brought them in by the summer.' },
    { id: 'hospital-lottery', m: 'hospital lottery', title: 'A town hall health service', date: 'counterfactual',
      text: 'In this life the 1945 Cabinet left the hospitals with the councils and charities. In reality every hospital was nationalised in 1948 under regional boards, though big differences between regions lasted for decades. The argument between national and local control of health care has never fully ended.' },
    { id: 'ncb', m: 'National Coal Board', title: 'The National Coal Board', date: 'from 1 January 1947',
      text: 'The Coal Industry Nationalisation Act 1946 took about 1,500 collieries into public ownership on Vesting Day, 1 January 1947, under the National Coal Board. Owners were compensated. Many miners had expected the pits to be run by the workers; they found many of the old managers still in charge.' },
    { id: 'winter-1947', m: 'Snow has blocked the railways', title: 'The winter of 1947', date: 'January–March 1947',
      text: 'One of the coldest winters on record. Blizzards cut off towns and stopped the coal trains; power stations ran short, electricity was cut for hours a day, factories closed and around two million people were temporarily out of work. The government\'s popularity never fully recovered.' },
    { id: 'abolition', m: 'suspend the death penalty', title: 'Abolishing hanging', date: '1948–65',
      text: 'Murder carried a mandatory death sentence. Abolitionists won a free vote in the Commons in 1948 to suspend hanging for five years, but the Lords threw it out. A Royal Commission followed; the case of Timothy Evans, hanged in 1950 and later shown to be innocent, changed many minds. Hanging for murder was suspended in 1965 and abolished in 1969.' },
    { id: 'keep-left', m: 'third force', title: 'Keep Left', date: '1947',
      text: 'A pamphlet by a group of Labour back-benchers in May 1947 calling for a socialist "third force" in Europe, independent of both America and the Soviet Union, and criticising Bevin\'s foreign policy. The Marshall Plan and the Communist takeovers in Eastern Europe soon overtook it, but the Keep Left group became the core of the later Bevanites.' },
    { id: 'free-at-use', m: 'Nobody is asking for money', title: 'Free at the point of use', date: 'from 1948',
      text: 'Before 1948 most working men were covered for a family doctor through National Insurance, but their wives, children and the old often were not, and hospital treatment, spectacles and dentures had to be paid for or begged from charity. In the NHS\'s first months the surgeries filled with people who had gone without for years.' },
  ];

  // Compile once; the first mention of each entry in a block of text is linked.
  TM.GLOSS.forEach((g) => { g.re = new RegExp(g.m); });
  TM.glossFind = (id) => TM.GLOSS.find((g) => g.id === id) || null;
})();
